INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1854', 'spa', 'Fuera, afuera — adverbio espacial de ubicación exterior o movimiento hacia afuera; sustantivado designa a los de afuera', 'Adverbio versátil de significado espacial — ''fuera'' o ''afuera'' — que el Nuevo Testamento emplea tanto en sentido literal como figurado. En su sentido espacial, marca movimiento físico o ubicación más allá de un límite: ser echado fuera (Mt 5:13), salir de una casa (Mt 12:46) o las tinieblas ''de afuera'' (Mt 8:12). En español, la distinción direccional se expresa con ''afuera'' y ''fuera de''. En un uso sustantivado de gran riqueza teológica, ''los de afuera'' designa a personas fuera del círculo de la fe: Jesús distingue a los de dentro de los de fuera en Marcos 4:11, y Pablo emplea la misma expresión (1 Co 5:12-13; Col 4:5) al tratar la relación de los creyentes con los no creyentes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1855', 'spa', 'Adverbio que significa ''desde afuera'' o ''exteriormente'', usado para señalar la superficie externa u origen exterior de algo en contraste con su interi', 'Adverbio que significa ''desde afuera'' o ''exteriormente'', usado para señalar la superficie externa u origen exterior de algo en contraste con su interior. En la memorable reprensión de Jesús a los fariseos (Mt 23:25-28), la palabra traza un agudo contraste entre el pulido religioso exterior y la corrupción interior — copas limpias por fuera pero inmundas por dentro, sepulcros blanqueados hermosos exteriormente pero llenos de huesos de muertos. Marcos 7:15, 18 distingue de manera similar lo que entra en una persona desde afuera frente a lo que sale de dentro del corazón. La evidencia multilingüe traduce uniformemente como ''desde afuera'', confirmando un único sentido espacial coherente en las trece apariciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1857', 'spa', 'exterior, de afuera; situado más allá de un espacio interior, en posición más externa', 'Este adjetivo describe lo que se encuentra en el exterior, más allá de un área interior. En las tres apariciones que tiene en el Nuevo Testamento —todas exclusivamente en el Evangelio de Mateo— se emplea en la solemne expresión «las tinieblas de afuera», describiendo el lugar de exclusión del reino de Dios donde hay llanto y crujir de dientes. La fuerza comparativa del término (derivado de ἔξω, «fuera») subraya la severidad de la separación respecto a la luz y el gozo de la presencia de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1858', 'spa', 'celebrar una fiesta, observar una festividad solemne', 'Verbo que significa observar o celebrar una fiesta o festividad, derivado de ἑορτή (fiesta). En el griego clásico incluía la celebración de victorias o festivales religiosos, y en Roma podía referirse a celebrar un triunfo. En 1 Corintios 5:8, Pablo exhorta a los creyentes a «celebrar la fiesta» (ἑορτάζωμεν) con panes sin levadura de sinceridad y verdad, transformando la imagen de la Pascua en una metáfora de la vida cristiana continua.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1859', 'spa', 'Fiesta, festividad — celebración religiosa o día santo, especialmente las principales fiestas de peregrinación judías.', 'Fiesta, festividad — celebración religiosa o día santo, especialmente las principales fiestas de peregrinación judías.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1860', 'spa', 'Promesa, compromiso solemne — especialmente las promesas pactuales de Dios a Abraham, Israel y los creyentes en Cristo', 'En el Nuevo Testamento este vocablo porta un peso que va mucho más allá de las promesas humanas ordinarias. Se refiere abrumadoramente a garantías divinas: la promesa de Dios a Abraham de descendencia y tierra (Hch 7:17; Gá 3:14-29), la promesa del Espíritu Santo en Pentecostés (Lc 24:49; Hch 1:4; 2:33) y la promesa de vida eterna en Cristo (2 Ti 1:1; Heb 9:15). Pablo construye su teología de la gracia frente a la ley en torno a este sustantivo, argumentando que la herencia viene por promesa, no por observancia legal (Gá 3:18; Ro 4:13-16). Hebreos lo presenta como ancla de la fe: quienes creyeron ''murieron sin haber recibido las promesas'', pero las vieron desde lejos (Heb 11:13, 39).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1861', 'spa', 'En el NT, ἐπαγγέλλομαι es abrumadoramente el verbo de la promesa divina — los compromisos pactuales de Dios con Abraham y sus descendientes, la promes', 'En el NT, ἐπαγγέλλομαι es abrumadoramente el verbo de la promesa divina — los compromisos pactuales de Dios con Abraham y sus descendientes, la promesa de vida eterna, del Espíritu Santo y del reino venidero. Pablo construye importantes argumentos teológicos sobre lo que Dios ''prometió'' (Ro 4:21; Gá 3:19; He 6:13; 10:23; 11:11), y el sustantivo relacionado ἐπαγγελία es uno de los grandes términos teológicos del NT. Un uso menor pero distinto aparece en las Epístolas Pastorales, donde significa profesar o reclamar públicamente algo — mujeres que profesan piedad (1 Ti 2:10) o quienes profesan conocimiento (1 Ti 6:21).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1863', 'spa', 'traer sobre, acarrear; causar que algo (frecuentemente adverso) recaiga sobre alguien', 'Este verbo compuesto significa traer o acarrear algo sobre alguien, generalmente con la connotación de introducir peligro, consecuencias o situaciones no deseadas. Hechos 5:28 lo emplea para describir la acción de hacer recaer la sangre de Jesús sobre los líderes judíos. En 2 Pedro (2:1 y 2:5) se usa para referirse a traer destrucción o juicio. En el griego clásico, su campo semántico incluía conducir ejércitos contra enemigos, azuzar perros contra una presa o persuadir a alguien hacia una acción, siempre con el sentido de causar que algo llegue o sea impuesto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1864', 'spa', 'contender fervientemente por algo, luchar con determinación', 'Verbo compuesto que significa luchar intensamente o pelear por algo con determinación. En el griego clásico podía referirse a competir en juegos atléticos o enfatizar un punto en la retórica. En Judas 3, se usa para exhortar a los creyentes a «contender ardientemente por la fe» (ἐπαγωνίζεσθαι τῇ πίστει) que fue entregada una vez para siempre a los santos. Se trata de una defensa vigorosa, incluso combativa, de la enseñanza apostólica frente a los falsos maestros.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1865', 'spa', 'congregarse, reunirse en gran número, aglomerarse progresivamente', 'Verbo en voz pasiva que significa reunirse o congregarse, con un prefijo que sugiere acumulación progresiva. En Lucas 11:29, se describe a las multitudes «apretujándose» o «reuniéndose en gran número» alrededor de Jesús para escucharle. El verbo transmite el sentido de muchedumbres crecientes, personas convergiendo desde distintas direcciones para formar una asamblea cada vez más numerosa e insistente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1866', 'spa', 'Epaíneto, un cristiano saludado por Pablo', 'Nombre propio que significa ''digno de alabanza'' o ''alabado'', perteneciente a un creyente en Roma a quien Pablo saluda con afecto en Romanos 16:5. Pablo lo llama ''mi amado'' y ''las primicias de Acaya (o Asia, según variantes textuales) para Cristo'', lo cual sugiere que Epaíneto fue uno de los primeros convertidos en esa región. Esta breve mención preserva el nombre de un líder cristiano primitivo por lo demás desconocido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1867', 'spa', 'Alabar, elogiar o expresar aprobación; usado tanto para elogio sincero como para alabanza retórica o irónica.', 'Verbo de afirmación pública que se emplea cuando alguien expresa aprobación o admiración hacia otra persona o sus acciones. En el NT aparece tanto en sentido positivo —como cuando Pablo elogia a los corintios por mantener las tradiciones (1 Corintios 11:2)— como con aguda ironía, cuando dice ''no os alabo'' por su conducta en la Cena del Señor (1 Corintios 11:17, 22). En Lucas 16:8 el amo alaba al administrador deshonesto por su astucia, mezclando sorpresa moral con genuino reconocimiento de ingenio. El español ''alabar'' y ''elogiar'' captan bien la calidez del elogio público que este verbo expresa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1868', 'spa', 'El sustantivo ἔπαινος (epainos) designa alabanza, elogio o aprobación, ya sea de parte de Dios, de las autoridades o de los creyentes. La verdadera ci', 'El sustantivo ἔπαινος (epainos) designa alabanza, elogio o aprobación, ya sea de parte de Dios, de las autoridades o de los creyentes. La verdadera circuncisión del corazón recibe su alabanza de Dios, no de los hombres (Ro 2:29), y los gobernantes dan elogio a quienes hacen el bien (Ro 13:3). En el regreso de Cristo, cada persona recibirá su reconocimiento de Dios (1 Co 4:5). Efesios emplea el término doxológicamente: la elección y la herencia son para alabanza de su gloria (Ef 1:6, 12, 14). Fil 4:8 exhorta a meditar en todo lo que sea digno de alabanza.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1869', 'spa', 'Levantar, alzar (ojos, manos, voz); en sentido figurado, exaltarse en orgullo; tambien izar una vela o ser elevado. Compuesto de ἐπί (''sobre'') y αἴρω ', 'Levantar, alzar (ojos, manos, voz); en sentido figurado, exaltarse en orgullo; tambien izar una vela o ser elevado. Compuesto de ἐπί (''sobre'') y αἴρω (''levantar''), este verbo en su forma mas simple describe el gesto fisico de alzar los ojos o las manos, una de las posturas de oracion mas comunes del mundo antiguo. Lucas lo usa con particular frecuencia: Jesus ''alzo sus ojos'' hacia sus discipulos antes de las Bienaventuranzas (Lc 6:20), y el cobrador de impuestos ni siquiera ''alzaba sus ojos'' al cielo (Lc 18:13). Pablo reutiliza el verbo poderosamente en 2 Co 10:5, donde todo pensamiento orgulloso que ''se levanta'' contra el conocimiento de Dios debe ser llevado cautivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1870', 'spa', 'El verbo ἐπαισχύνομαι (epaischynomai) significa avergonzarse de una persona, un mensaje o una lealtad. Jesús advierte que quien se avergüence de él y ', 'El verbo ἐπαισχύνομαι (epaischynomai) significa avergonzarse de una persona, un mensaje o una lealtad. Jesús advierte que quien se avergüence de él y de sus palabras, el Hijo del Hombre se avergonzará de esa persona en su venida (Mr 8:38; Lc 9:26). Pablo declara que no se avergüenza del evangelio (Ro 1:16) y exhorta a Timoteo a no avergonzarse del testimonio del Señor ni de las cadenas de Pablo (2 Ti 1:8, 12, 16). Del lado divino, Dios no se avergüenza de ser llamado su Dios, porque ha preparado una ciudad para los fieles (Heb 2:11; 11:16).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1872', 'spa', 'Seguir de cerca, acompañar; dedicarse a algo con empeño o perseverancia', 'Formado a partir de ἐπί (''sobre, tras'') y ἀκολουθέω (''seguir''), este verbo intensifica la idea de seguimiento con cercanía y persistencia. Sus usos en el NT abarcan un amplio espectro: las señales confirmatorias que ''siguen'' a la proclamación del evangelio (Marcos 16:20), el historial de buenas obras a las que una viuda se ha ''dedicado'' con esmero (1 Timoteo 5:10), los pecados que ''siguen'' a ciertas personas hasta el juicio (1 Timoteo 5:24) y los sufrimientos de Cristo cuyo ejemplo los creyentes deben ''seguir'' (1 Pedro 2:21).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1873', 'spa', 'oír, escuchar, prestar oído, atender favorablemente', 'Verbo que significa oír o escuchar, frecuentemente con el matiz de atención favorable o de respuesta a una petición. En 2 Corintios 6:2, Pablo cita a Isaías: ''En tiempo aceptable te escuché'' (ἐπήκουσά σου). El verbo puede implicar no solamente percepción auditiva sino acción responsiva: Dios que oye y responde a la oración. En el uso clásico incluía también el sentido de escuchar algo de manera indirecta o por casualidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1874', 'spa', 'escuchar atentamente, prestar oído', 'Verbo compuesto sinónimo de ἐπακούω que significa escuchar con atención o prestar oído. En Hechos 16:25, se describe a los presos ''escuchando'' (ἐπηκροῶντο) a Pablo y Silas mientras oraban y cantaban himnos a medianoche. El tiempo imperfecto sugiere una acción continua: los demás prisioneros estaban escuchando activamente, cautivados por esta adoración inusual en lo profundo de la cárcel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1875', 'spa', 'cuando, siempre que; conjunción temporal que señala el momento de un suceso', 'Forma tardía de la conjunción ἐπήν, esta palabra funciona como un marcador temporal sencillo que significa «cuando» o «siempre que». Introduce cláusulas subordinadas que precisan el momento de los eventos. Aparece en contextos narrativos: Herodes buscando al niño (Mateo 2:8), un hombre fuerte siendo vencido (Lucas 11:22) y la condición del ojo que afecta a todo el cuerpo (Lucas 11:34). La conjunción simplemente indica coincidencia o secuencia temporal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1876', 'spa', 'necesario, obligatorio, de necesidad', 'Adverbio que significa ''por necesidad'' o ''de manera obligatoria'', derivado de ἀνάγκη (necesidad). En Hechos 15:28 se emplea en el decreto apostólico dirigido a los creyentes gentiles: ''Pareció bien al Espíritu Santo y a nosotros no imponeros mayor carga que estas cosas necesarias'' (ἐπάναγκες). El término distingue los requisitos esenciales de las prácticas opcionales, señalando estándares mínimos innegociables.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1877', 'spa', 'hacerse a la mar, volver; término náutico para zarpar o regresar en barca', 'Este verbo compuesto posee un amplio rango de significados en el griego clásico —agitar, reconducir, restaurar—, pero en el Nuevo Testamento aparece exclusivamente en contextos náuticos, con el sentido de hacerse a la mar o regresar en barca. Lucas lo utiliza tres veces: Jesús volviendo de Betania (Mateo 21:18), apartándose un poco de la orilla (Lucas 5:3) y la célebre orden de navegar mar adentro (Lucas 5:4). El verbo capta el movimiento de embarcaciones alejándose de la costa o regresando al puerto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1878', 'spa', 'recordar, traer a la memoria', 'Verbo compuesto que significa recordar o traer algo a la mente de alguien. En Romanos 15:15, Pablo dice que ha escrito ''recordándoos'' (ἐπαναμιμνῄσκων) a los creyentes verdades que ya conocen. El prefijo ἐπι- sugiere devolver algo a la conciencia, refrescar la memoria en lugar de introducir información nueva. Se trata de un refuerzo pastoral de la doctrina ya conocida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1882', 'spa', 'corrección, restauración a un estado recto; enmienda constructiva mediante la Escritura', 'Sustantivo que significa corrección, enmienda o el acto de enderezar lo torcido. En 2 Timoteo 3:16, Pablo declara que toda la Escritura es útil para la «corrección» (ἐπανόρθωσιν), uno de cuatro propósitos junto con la enseñanza, la reprensión y la instrucción en justicia. El término no se limita a señalar el error, sino que implica restaurar activamente a la persona, realineándola con el estándar correcto. Es una acción terapéutica, no punitiva, que busca llevar la conducta o el pensamiento desviado de vuelta al camino recto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1883', 'spa', 'Encima, sobre, por encima (posicion espacial); tambien ''mas de'' en expresiones comparativas de cantidad o grado. ἐπάνω funciona principalmente como ad', 'Encima, sobre, por encima (posicion espacial); tambien ''mas de'' en expresiones comparativas de cantidad o grado. ἐπάνω funciona principalmente como adverbio y preposicion espacial que significa ''encima'' o ''sobre'', colocando una cosa por encima de otra. Una estrella se detuvo encima de donde estaba el nino (Mt 2:9), una ciudad asentada sobre un monte no puede esconderse (Mt 5:14) y vestiduras se colocan sobre un asno (Mt 21:7). La palabra se extiende al ambito comparativo: el perfume pudo haberse vendido ''por mas de'' trescientos denarios (Mc 14:5), y Cristo aparecio a ''mas de'' quinientos de una vez (1 Co 15:6).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1884', 'spa', 'socorrer, asistir, aliviar; prestar ayuda especialmente a los necesitados', 'Este verbo significa tener la fuerza suficiente para ayudar, asistir o aliviar a alguien en necesidad. En el uso clásico podía significar repeler un daño o brindar apoyo. En el Nuevo Testamento aparece exclusivamente en 1 Timoteo 5, dentro de las instrucciones de Pablo sobre qué viudas debe sostener la iglesia. La palabra conlleva el sentido de proporcionar alivio práctico y asistencia, especialmente a personas vulnerables que carecen de otros recursos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1886', 'spa', 'morada, habitación, finca rural; lugar de residencia fija', 'Sustantivo que designa una morada, habitación o propiedad rural. En el uso clásico abarcaba edificaciones agrícolas, casas de campo, alojamientos militares o aldeas sin murallas. En Hechos 1:20, Pedro cita el Salmo 69:25 aplicándolo a Judas: «Sea satisfecho su habitación (ἔπαυλις) en desolación.» El término evoca una residencia establecida o hacienda que, a causa de la traición de Judas, queda maldita con el vacío. Esta desolación prepara el terreno para la elección de un apóstol que ocupe el puesto ministerial abandonado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1887', 'spa', 'Al dia siguiente, al otro dia; adverbio temporal que indica el dia que sigue. ἐπαύριον es un adverbio temporal que significa ''al dia siguiente'' o ''al ', 'Al dia siguiente, al otro dia; adverbio temporal que indica el dia que sigue. ἐπαύριον es un adverbio temporal que significa ''al dia siguiente'' o ''al otro dia''. Funciona como un recurso de secuenciacion narrativa que avanza la historia un dia. El Evangelio de Juan lo usa con particular frecuencia para construir la semana inaugural del ministerio de Jesus: Juan el Bautista ve a Jesus ''al dia siguiente'' (Jn 1:29), luego nuevamente ''al dia siguiente'' (1:35), y despues Jesus va a Galilea ''al dia siguiente'' (1:43). Tambien aparece prominentemente en Hechos para seguir los viajes de Pablo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1888', 'spa', 'en el mismo acto, en flagrante delito, con las manos en la masa', 'Expresión que significa «sorprendido en el acto» o «en flagrante delito», derivada de αὐτόφωρος (autodetectado). En Juan 8:4, los escribas y fariseos traen ante Jesús a una mujer «sorprendida en el mismo acto» (ἐπ᾽ αὐτοφώρῳ) de adulterio. Se trata de una evidencia irrefutable, un testimonio ocular que no deja lugar a negación ni duda sobre el hecho. Sin embargo, pese a esta prueba contundente, la respuesta de Jesús redirige la atención de la culpa de la mujer a la hipocresía de los acusadores, ofreciendo misericordia en lugar del juicio a pedradas que ellos exigían.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1889', 'spa', 'Epafras; nombre propio de un colaborador de Pablo', 'Epafras es un nombre propio, probablemente forma abreviada de Epafrodito (aunque se refiere a una persona distinta del mensajero de Filipos). Este fiel ministro llevó el evangelio a Colosas y mantuvo una profunda preocupación por las iglesias del valle del Lico. Pablo lo llama «amado consiervo» y «fiel ministro de Cristo», y destaca sus constantes oraciones por los creyentes colosenses. El nombre evoca calidez y entrega en el ministerio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1890', 'spa', 'espumar, arrojar espuma; hacer brotar inmundicia como olas turbulentas', 'Verbo que significa espumar o producir espuma, usado literalmente de las olas y metafóricamente de la conducta vergonzosa. En Judas 13, se emplea en sentido figurado para describir a los falsos maestros como «fieras olas del mar, que espuman (ἐπαφρίζοντα) su propia vergüenza». La imagen evoca aguas turbulentas y caóticas que arrojan a la superficie desechos e inmundicia, simbolizando la exhibición pública de la corrupción moral. El verbo sugiere una exposición violenta y descontrolada de la podredumbre interior.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1893', 'spa', 'ya que, porque; de lo contrario — conjunción causal que expone razones o introduce una alternativa contrafactual', 'ya que, porque; de lo contrario — conjunción causal que expone razones o introduce una alternativa contrafactual');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1894', 'spa', 'Conjunción que cumple predominantemente una función causal en el Nuevo Testamento, introduciendo la razón o fundamento de lo que sigue. Pablo declara ', 'Conjunción que cumple predominantemente una función causal en el Nuevo Testamento, introduciendo la razón o fundamento de lo que sigue. Pablo declara que puesto que el mundo mediante su sabiduría no conoció a Dios, agradó a Dios salvar por medio de la locura de la predicación (1 Co 1:21). En una única aparición temporal en Lc 7:1, introduce una cláusula de tiempo —cuando Jesús terminó sus palabras— señalando el paso de la razón a la secuencia temporal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1895', 'spa', 'puesto que, ya que, dado que (conjunción causal enfática)', 'Conjunción causal reforzada que significa «puesto que ciertamente» o «dado que en efecto», formada por la combinación de ἐπεί (puesto que) con la partícula enfática περ. En Lucas 1:1, el evangelista abre su relato con esta palabra: «Puesto que (ἐπειδήπερ) muchos han emprendido la tarea de compilar un relato...» Lucas la usa para reconocer los testimonios evangélicos previos como base factual de su propia obra, cuidadosamente investigada. La conjunción establece la premisa: dado que otros ya han escrito y los testigos oculares han transmitido estos hechos, Lucas presenta ahora su relato ordenado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1897', 'spa', 'puesto que en verdad, ya que ciertamente (forma enfática de ἐπεί con la partícula intensiva περ)', 'Conjunción compuesta que combina ἐπεί (''puesto que'', ''porque'') con la partícula intensiva περ. Esta fusión produce una expresión causal o temporal enfática: ''puesto que en verdad'' o ''dado que ciertamente''. En los textos clásicos se emplea para reforzar el razonamiento causal, añadiendo peso a un argumento al subrayar la certeza o evidencia de la premisa. La partícula περ a lo largo de la literatura griega funciona para intensificar o destacar la palabra que acompaña.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1898', 'spa', 'introducción, acto de traer algo nuevo en reemplazo o complemento de lo anterior', 'Sustantivo que designa el acto de introducir o traer algo adicional, generalmente para reemplazar o complementar lo que ya existía. En Hebreos 7:19 se habla de «la introducción (ἐπεισαγωγή) de una mejor esperanza» tras la anulación del mandamiento anterior. El término no implica una simple adición, sino una sustitución: lo antiguo se deja de lado para dar paso a algo superior. Aquí marca la transición del régimen mosaico al nuevo pacto en Cristo, donde los creyentes acceden directamente a Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1899', 'spa', 'Despues, luego, a continuacion — adverbio temporal-secuencial que marca lo que viene a continuacion en una serie. ἔπειτα es un adverbio de secuencia q', 'Despues, luego, a continuacion — adverbio temporal-secuencial que marca lo que viene a continuacion en una serie. ἔπειτα es un adverbio de secuencia que marca el siguiente paso en una cadena temporal o logica. Compuesto de ἐπί (''sobre'') y εἶτα (''entonces''), sirve como un marcador mas deliberado que el simple ''entonces'' (τότε), frecuentemente enumerando etapas ordenadas. Pablo lo usa magistralmente en 1 Co 15:5-8 para listar las apariciones de la resurreccion en orden — ''despues a los doce... despues a mas de quinientos... despues a Jacobo... despues a todos los apostoles'' — y nuevamente en 15:23-24 para secuenciar eventos escatologicos. En 1 Co 12:28 clasifica los dones espirituales: ''primero apostoles, luego profetas, luego maestros''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1900', 'spa', 'más allá, al otro lado; indica distancia espacial o temporal extrema', 'Adverbio que significa «más allá» o «del otro lado», usado con genitivo para indicar distancia espacial o temporal. En Hechos 7:43 se cita Amós 5:27: «Os transportaré más allá (ἐπέκεινα) de Babilonia.» El término señala un exilio hacia tierras lejanas, más allá de los límites inmediatos. En el uso clásico también podía referirse a tiempos anteriores o futuros. Aquí marca un destierro total como juicio divino contra la idolatría de Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1901', 'spa', 'extenderse hacia adelante, estirarse con esfuerzo hacia una meta', 'Verbo compuesto que significa extenderse o estirarse hacia adelante, con la idea de esforzarse intensamente hacia un objetivo. En Filipenses 3:13, Pablo se describe «extendiéndose» (ἐπεκτεινόμενος) hacia lo que está delante, olvidando lo que queda atrás. El verbo evoca la imagen atlética de un corredor que se inclina en la carrera, con cada músculo tensado hacia la meta. No se trata de una espera pasiva, sino de una búsqueda activa y concentrada del llamamiento celestial de Dios en Cristo Jesús.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1903', 'spa', 'ropa exterior, manto o capa que se lleva sobre otras prendas', 'Sustantivo que designa una prenda exterior o manto que se lleva sobre la ropa interior, derivado de ἐνδύω (vestir) con el prefijo ἐπι- (sobre). En Juan 21:7, Pedro se pone su «ropa exterior» (ἐπενδύτην) antes de lanzarse al mar para ir al encuentro de Jesús resucitado. El término distingue esta prenda superior de la túnica interior, indicando que Pedro estaba trabajando con vestimenta mínima y se cubrió con el manto por pudor o respeto antes de nadar hacia el Señor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1904', 'spa', 'El verbo ἐπέρχομαι (eperchomai) significa venir sobre, llegar o sobrevenir a alguien o algo. Su estructura compuesta (ἐπί + ἔρχομαι) expresa un movimi', 'El verbo ἐπέρχομαι (eperchomai) significa venir sobre, llegar o sobrevenir a alguien o algo. Su estructura compuesta (ἐπί + ἔρχομαι) expresa un movimiento dirigido hacia un objetivo que culmina en su llegada. En Lc 1:35 el Espíritu Santo ''vendrá sobre'' María, y en Hch 1:8 el poder ''vendrá sobre'' los discípulos, describiendo ambos una visitación divina desde lo alto. Lc 21:26 advierte sobre terrores que ''sobrevendrán'' al mundo habitado, y Lc 11:22 habla de un hombre más fuerte que ''viene sobre'' un adversario armado. Hch 14:19 registra judíos que ''llegaron desde'' Antioquía e Iconio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1905', 'spa', 'Preguntar, interrogar, inquirir — dirigir una pregunta a alguien para obtener información o ponerlo a prueba', 'El verbo ἐπερωτάω (''preguntar, interrogar, inquirir'') combina el prefijo ἐπι- con ἐρωτάω (''preguntar''), intensificando la noción de indagación dirigida. Sus 56 apariciones neotestamentarias se concentran marcadamente en los Evangelios sinópticos, donde describe las preguntas que discípulos, multitudes, fariseos, saduceos y Pilato dirigen a Jesús, así como las que Jesús dirige a otros. El vocablo cubre todo el espectro: desde la búsqueda genuina de información (Mr 9:11, los discípulos preguntando sobre Elías) hasta la prueba hostil (Mt 22:35, un legista probando a Jesús) y el interrogatorio judicial (Mt 27:11, Pilato interrogando a Jesús). Un núcleo semántico unitario se confirma en todas las lenguas: dirigir una pregunta a alguien.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1906', 'spa', 'pregunta, consulta; compromiso solemne, petición o apelación formal', 'Sustantivo que significa pregunta o consulta, pero que también desarrolló el sentido de compromiso solemne o petición formal. En 1 Pedro 3:21, el bautismo salva «no como eliminación de la suciedad del cuerpo, sino como petición (ἐπερώτημα) a Dios de una buena conciencia.» Los eruditos debaten si esto significa el compromiso del creyente ante Dios o una súplica de purificación. El término jurídico latino stipulatio (acuerdo formal) influyó en la interpretación posterior, sugiriendo una transacción pactual, no un mero ritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1907', 'spa', 'Presentar, prestar atención, notar; ofrecer algo o fijar la mente cuidadosamente en algo.', 'Verbo compuesto versátil (ἐπί + ἔχω, ''sostener sobre'') con dos sentidos distinguibles en el NT. Puede significar presentar u ofrecer algo hacia afuera, como en presentar la palabra de vida (Fil 2:16). También significa prestar atención cuidadosa, fijar la mirada o el pensamiento en alguien o algo: los invitados observando dónde se sentaban (Luc 14:7), el cojo prestando atención a Pedro y Juan (Hch 3:5), y Pablo exhortando a Timoteo a prestar atención a sí mismo y a su enseñanza (1 Tim 4:16). Las traducciones al español — presta-atención, notando — resaltan el sentido de atención vigilante, mientras que ''presentar'' capta el significado dirigido hacia afuera.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1908', 'spa', 'Maltratar, ultrajar, injuriar; tratar a alguien con desprecio, abuso verbal o persecución hostil', 'Este verbo significa amenazar de forma abusiva, hablar con desprecio de alguien o actuar contra esa persona de manera ultrajante. En el uso clásico incluye oposición insolente y trato insultante. En el Nuevo Testamento aparece en contextos de persecución y calumnia contra los creyentes. Jesús ordena amar a quienes nos maltratan (Mateo 5:44, Lucas 6:28), y Pedro anima a una conducta ejemplar que avergüence a quienes ultrajan a los cristianos (1 Pedro 3:16).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1909', 'spa', 'Sobre, encima de, por encima de; en, junto a; contra; con base en, acerca de — contacto espacial, autoridad, oposición y referencia', 'Una preposición versátil que expresa contacto físico con una superficie, posición de autoridad sobre algo o alguien, hostilidad u oposición, el fundamento o base de algo, o el tema del que se habla.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1910', 'spa', 'Subir a, pisar, embarcar (en una nave) o poner pie en un lugar; movimiento físico de montar o llegar.', 'Describe el acto físico de pisar una superficie, embarcar en una nave o llegar a un lugar entrando en él. En el griego clásico podía significar montar a caballo o pisar tierra; en el NT aparece principalmente en narrativas de viaje que involucran travesías marítimas. Pablo embarca en naves (Hechos 21:2), pone pie en provincias (Hechos 20:18; 25:1), y en Mateo 21:5 Jesús entra en Jerusalén montado sobre un asno. El español ''embarcarse'' capta bien el sentido marítimo, mientras que ''montar'' refleja el matiz clásico más antiguo de subirse a un animal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1911', 'spa', 'Arrojar o echar sobre; echar mano (prender); colocar encima; de olas, golpear contra; reflexivamente, reflexionar; de una porcion, corresponder a algu', 'Arrojar o echar sobre; echar mano (prender); colocar encima; de olas, golpear contra; reflexivamente, reflexionar; de una porcion, corresponder a alguien. Verbo compuesto versatil (ἐπί + βάλλω, ''arrojar sobre'') cuyo alcance va desde el arresto violento hasta la reflexion silenciosa. Su uso mas frecuente en el NT involucra echar mano a alguien para prenderlo, como cuando los guardias del templo intentan arrestar a Jesus en Jn 7:30. Pero el mismo verbo describe colocar vestiduras sobre un pollino (Mc 11:7), olas estrellándose sobre un barco en una tormenta galileana (Mc 4:37) y, memorablemente, el llanto angustiado de Pedro cuando canta el gallo (Mc 14:72).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1912', 'spa', 'Ser carga, gravar; imponerse como peso económico o emocional sobre alguien', 'Este verbo significa ser una carga o pesar sobre alguien, especialmente en el ámbito económico o emocional. Pablo lo emplea exclusivamente en sus cartas para describir su decisión deliberada de no ser una carga para las iglesias que servía. En el uso clásico incluía la idea de estar sobrecargado o fuertemente presionado. En el contexto ministerial de Pablo, refleja su práctica de sostenerse a sí mismo para no representar un peso económico para los nuevos creyentes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1913', 'spa', 'Montar, poner encima; colocar a alguien sobre un animal o medio de transporte', 'Este verbo significa poner a alguien sobre algo, generalmente montar a una persona sobre un animal para transportarla. Todos los usos neotestamentarios involucran colocar personas sobre animales en contextos de cuidado o traslado oficial. El buen samaritano pone al herido sobre su propia cabalgadura (Lucas 10:34), los seguidores hacen montar a Jesús sobre un pollino (Lucas 19:35), y los soldados romanos preparan cabalgaduras para el traslado de Pablo (Hechos 23:24).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1914', 'spa', 'Mirar, poner los ojos en; dirigir la mirada con atención o favor hacia alguien o algo', 'Este verbo compuesto significa mirar con atención o considerar algo detenidamente, con frecuencia con el matiz de atención favorable u observación cuidadosa. En el uso clásico incluye observar con esmero o contemplar algo. En el Nuevo Testamento aparece en el Magnificat de María, donde Dios puso sus ojos en su humilde condición (Lucas 1:48), en la súplica de un padre para que Jesús mire a su hijo (Lucas 9:38), y en la crítica de Santiago contra la parcialidad al fijarse en la ropa fina (Santiago 2:3).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1915', 'spa', 'Remiendo, parche; trozo de tela cosido sobre una prenda para repararla', 'De ἐπί (''sobre'') y βάλλω (''lanzar, poner''), este sustantivo significa literalmente ''algo puesto encima''. En sus cuatro apariciones neotestamentarias se refiere a un parche de tela nueva usado para remendar una prenda vieja. Jesús emplea esta imagen cotidiana en las parábolas sinópticas (Mateo 9:16; Marcos 2:21; Lucas 5:36) para ilustrar por qué su enseñanza del nuevo pacto no puede simplemente ''parchearse'' sobre los viejos moldes religiosos: la tela nueva tiraría de la vieja, agrandando el roto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1916', 'spa', 'invocar, clamar a; aclamar, llamar a gritos o con urgencia', 'Verbo que describe el acto de invocar a alguien o clamar, a menudo con urgencia o emoción intensa. Aparece en contextos de invocación a deidades, lamentos fúnebres dirigidos a los difuntos, o peticiones de auxilio. En voz media puede significar clamar contra alguien, o bien aclamar y aplaudir. El uso clásico incluye la imagen de perros de caza que ladran al captar un rastro. El prefijo compuesto ἐπι- añade dirección: clamar hacia o sobre una persona o divinidad, haciéndolo especialmente apto para la oración y la invocación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1917', 'spa', 'Complot, conspiración, maquinación tramada contra alguien', 'De ἐπί (''contra'') y βουλή (''consejo, plan''), este sustantivo designa un plan deliberado y hostil urdido contra otra persona. Las cuatro apariciones neotestamentarias se encuentran en Hechos y giran en torno a complots dirigidos contra Pablo: la conspiración judía en Damasco (9:24), la trama que desvió sus planes de viaje en Grecia (20:3), las ''asechanzas de los judíos'' que soportó a lo largo de su ministerio (20:19) y el complot de asesinato comunicado al tribuno romano (23:30). El vocablo connota secretismo e intención maliciosa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1918', 'spa', 'casarse con la viuda del hermano (matrimonio por levirato)', 'Verbo que designa el acto de casarse con la viuda del propio hermano, cumpliendo el deber del levirato prescrito en Deuteronomio 25:5-10. En Mateo 22:24, los saduceos citan la ley mosaica: «Si un hombre muere sin hijos, su hermano deberá casarse (ἐπιγαμβρεύσει) con la viuda». Este término técnico se refiere específicamente a esta obligación de parentesco destinada a preservar el linaje familiar y la herencia. Los saduceos emplean esta ley para construir un enigma hipotético sobre la resurrección.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1919', 'spa', 'Terrenal, perteneciente o propio de la tierra, en contraste con lo celestial o divino.', 'Adjetivo que traza una línea nítida entre lo que pertenece a la tierra y lo que pertenece al cielo. Jesús emplea este contraste en su diálogo con Nicodemo: ''Si os he dicho cosas terrenales y no creéis, ¿cómo creeréis si os dijere las celestiales?'' (Juan 3:12). Pablo desarrolla el contraste cosmológicamente en 1 Corintios 15:40, distinguiendo cuerpos terrenales de celestiales, y existencialmente en 2 Corintios 5:1, donde nuestra morada terrenal da paso a una casa eterna. En el gran himno cristológico de Filipenses 2:10, toda rodilla se dobla: en el cielo, en la tierra y debajo de la tierra. El español ''terrenal'' conserva el sentido de limitación y transitoriedad inherente a lo que es meramente de este mundo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1920', 'spa', 'sobrevenir, levantarse (dicho del viento)', 'Verbo que significa surgir después, llegar subsecuentemente o levantarse. En Hechos 28:13 se emplea para describir un viento del sur que «se levantó» (ἐπιγενομένου), permitiendo al barco de Pablo continuar su travesía. En el uso clásico incluía el sentido de posteridad que viene después o de eventos que se suceden en secuencia. Aquí el contexto náutico sugiere un viento favorable que surge tras un período de espera, marcando el momento providencial para zarpar hacia Puteoli.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1921', 'spa', 'Reconocer, llegar a conocer, discernir; percibir plenamente, admitir o identificar a una persona, un hecho o una verdad.', 'Reconocer, llegar a conocer, discernir; percibir plenamente, admitir o identificar a una persona, un hecho o una verdad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1922', 'spa', 'Conocimiento pleno; reconocimiento profundo y experiencial, especialmente de Dios y de la verdad espiritual. Mas que mera informacion, este sustantivo', 'Conocimiento pleno; reconocimiento profundo y experiencial, especialmente de Dios y de la verdad espiritual. Mas que mera informacion, este sustantivo compuesto (ἐπί + γνῶσις) transmite un conocimiento completo, personal y a menudo transformador. Pablo lo usa repetidamente para describir la creciente comprension del creyente sobre el caracter y la voluntad de Dios, ya sea lamentando que la gente ''no tuvo a bien reconocer a Dios'' (Ro 1:28) o pidiendo que los efesios reciban ''espiritu de sabiduria y de conocimiento de el'' (Ef 1:17). Es el tipo de conocimiento que transforma la conducta y profundiza la fe, no la mera acumulacion de datos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1923', 'spa', 'Inscripción, epígrafe; texto escrito sobre una moneda, monumento o letrero para identificar o designar algo.', 'Sustantivo derivado de ἐπιγράφω (''escribir sobre''), que se refiere a cualquier texto inscrito en una superficie con fines de identificación o proclamación. En los Evangelios aparece en dos contextos memorables: la inscripción en una moneda romana — ''¿De quién es esta imagen e inscripción?'' pregunta Jesús sobre el denario (Mat 22:20; Mar 12:16; Luc 20:24) — y el cargo escrito sobre la cruz de Jesús (Mar 15:26; Luc 23:38). El término español inscripción traduce fielmente esta palabra, subrayando su carácter técnico y documental. Ya sea en monedas o en el titulus crucis, el vocablo señala una etiqueta pública y autoritativa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1924', 'spa', 'Escribir sobre, inscribir; grabar o registrar texto en una superficie, ya sea literal o figuradamente.', 'Contraparte verbal de ἐπιγραφή (''inscripción''), que significa escribir o grabar sobre una superficie. Sus usos en el NT abarcan lo literal y lo profundamente teológico: el cargo inscrito sobre la cruz de Jesús (Mar 15:26), la inscripción del altar ''Al Dios no conocido'' que Pablo observó en Atenas (Hch 17:23), y — con mayor profundidad — la promesa de Dios de inscribir sus leyes en los corazones y mentes de su pueblo (Heb 8:10; 10:16), haciendo eco de la profecía del nuevo pacto de Jeremías. Apocalipsis 21:12 describe los nombres de las tribus de Israel inscritos en las puertas de la nueva Jerusalén. Las traducciones inscribiré e inscrita captan el acto de grabado permanente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1925', 'spa', 'Mostrar, exhibir o demostrar algo visual o evidencialmente; presentar o señalar.', 'Verbo que significa mostrar, exhibir o demostrar, ya sea un objeto, una persona o una evidencia. En los Evangelios, Jesús pide a los fariseos que le muestren la moneda del tributo (Mateo 22:19) y los discípulos le señalan los edificios del templo (Mateo 24:1). Al leproso sanado se le ordena mostrarse a los sacerdotes (Lucas 17:14). En Hechos 9:39, las viudas de Jope muestran a Pedro las túnicas que Dorcas había confeccionado. El verbo conlleva una nota de exhibición o prueba: no se trata simplemente de ver, sino de presentar deliberadamente algo para su inspección o verificación. El español ''mostrar'' y ''demostrar'' captan esta fuerza demostrativa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1928', 'spa', 'añadir disposiciones, agregar cláusulas (a un pacto o testamento)', 'Verbo compuesto que significa agregar provisiones a un acuerdo existente, especialmente a un pacto o documento legal. En Gálatas 3:15, Pablo lo emplea en su argumento: incluso un pacto humano, una vez ratificado, no puede ser anulado ni recibir añadiduras (ἐπιδιατάσσεται). El verbo sugiere una modificación o enmienda no autorizada. Pablo utiliza esta analogía jurídica para argumentar que la ley mosaica, llegada 430 años después de Abraham, no puede alterar la promesa del pacto de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1929', 'spa', 'Dar directamente, entregar en mano a alguien; entregar un documento formalmente; ceder o dar paso (náutico).', 'Verbo compuesto (ἐπί + δίδωμι) que significa dar algo directamente en las manos de alguien. La mayoría de las apariciones en el Nuevo Testamento describen el acto íntimo de entregar algo a una persona: un padre dando pan o pescado a un hijo que pide (Mt 7:9-10; Lc 11:11-12), o Jesús recibiendo el rollo de Isaías que le entregan en la sinagoga (Lc 4:17). El español distingue acertadamente entre el cotidiano ''daba/dará'' para el dar personal y ''entregaron'' para la entrega formal de la carta de Jerusalén (Hch 15:30). Un uso náutico aparece en Hechos 27:15, donde la nave ''cedió'' ante el viento, capturado con precisión por el español ''cediendo''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1930', 'spa', 'poner en orden, organizar, corregir lo deficiente', 'Verbo compuesto que significa enderezar, organizar debidamente o corregir deficiencias. En Tito 1:5, Pablo instruye a Tito: «Te dejé en Creta para que pusieras en orden (ἐπιδιορθώσῃ) lo que falta y nombraras ancianos». El término sugiere completar reformas inconclusas o corregir problemas organizativos. Se trata de una labor administrativa: establecer la estructura eclesiástica apropiada donde esta era deficiente, asegurando que cada ciudad contara con liderazgo calificado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1931', 'spa', 'ponerse, ocultarse (dicho del sol)', 'Verbo que significa ponerse u ocultarse, usado especialmente para cuerpos celestes. En Efesios 4:26, Pablo cita el Salmo 4:4 con un matiz particular: «Airaos pero no pequéis; no se ponga (ἐπιδυέτω) el sol sobre vuestro enojo». El fenómeno astronómico literal se convierte en un límite temporal: la ira no debe persistir más allá de la puesta del sol. Esto establece un plazo para la reconciliación, utilizando el ciclo natural del día para limitar la duración del conflicto humano.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1933', 'spa', 'Amable, indulgente, bondadoso; describe una disposición justa y razonable que no insiste en derechos estrictos.', 'Denota una cualidad de carácter que es amable, paciente y dispuesta a ceder en lugar de exigir justicia estricta. El concepto griego contrasta deliberadamente con el legalismo rígido: una persona ἐπιεικής ejerce una razonabilidad llena de gracia. Pablo insta a los creyentes en Filipos a que su amabilidad sea conocida por todos (Fil 4:5), y aparece como rasgo requerido para los obispos (1 Tim 3:3) y como marca de la sabiduría celestial (Stg 3:17). El español ''amable'' y ''gentil'' captan la calidez de este término, aunque ninguno transmite plenamente el matiz de renunciar a los propios derechos legítimos en favor de la paz.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1934', 'spa', 'Forma intensificada de ζητέω (buscar), donde el prefijo ἐπι- añade persistencia y urgencia a la búsqueda. Cuando Jesús dice ''las naciones buscan afano', 'Forma intensificada de ζητέω (buscar), donde el prefijo ἐπι- añade persistencia y urgencia a la búsqueda. Cuando Jesús dice ''las naciones buscan afanosamente todas estas cosas'' (Mt 6:32; Lc 12:30), el verbo expone un anhelo ansioso de seguridad material. Cuando ''una generación malvada busca señal'' (Mt 12:39; 16:4), revela una demanda obstinada de pruebas. Sin embargo, la misma intensidad puede ser noble: los patriarcas ''buscaban una patria'' (He 11:14), y las multitudes en Capernaúm ''buscaban'' a Jesús porque habían probado algo real (Lc 4:42).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1935', 'spa', 'condenado a muerte, destinado a la ejecución', 'Adjetivo que significa sentenciado a muerte o condenado a morir, usado frecuentemente para gladiadores o criminales condenados. En 1 Corintios 4:9, Pablo dice que Dios ha exhibido a los apóstoles «como condenados a muerte» (ἐπιθανατίους), los últimos de todos, como hombres sentenciados a la arena. El término evoca el espectáculo público de los condenados, exhibidos para entretenimiento antes de su inevitable ejecución. Pablo emplea esta cruda imagen para contrastar el sufrimiento apostólico con el orgullo de los corintios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1936', 'spa', 'Imposición, acción de poner encima (especialmente la imposición de manos en un rito religioso)', 'De ἐπιτίθημι (''colocar sobre''), este sustantivo se refiere al acto de poner algo encima y en el NT se usa exclusivamente para la imposición de manos en contextos de ordenación, comisión o bendición. Aparece en pasajes fundamentales sobre el orden eclesial: las manos de los apóstoles que transmiten el Espíritu (Hechos 8:18), el don que Timoteo recibió mediante la imposición de manos del presbiterio (1 Timoteo 4:14; 2 Timoteo 1:6) y entre las doctrinas elementales mencionadas en Hebreos 6:2.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1937', 'spa', 'Desear intensamente: ya sea anhelar algo bueno o codiciar lo prohibido. Verbo de deseo interior intenso cuya coloración moral depende enteramente de s', 'Desear intensamente: ya sea anhelar algo bueno o codiciar lo prohibido. Verbo de deseo interior intenso cuya coloración moral depende enteramente de su objeto. Cuando Jesús dice «¡Cuánto he deseado comer esta Pascua con vosotros!» (Lucas 22:15), la palabra resplandece con anhelo santo. Cuando profetas y reyes «desearon ver» lo que los discípulos ven (Mateo 13:17), expresa anticipación sagrada. Pero en la tradición del Decálogo —«no codiciarás» (Romanos 7:7; 13:9)— y en las advertencias sobre el deseo carnal (Mateo 5:28; 1 Corintios 10:6; Gálatas 5:17), carga el peso del anhelo pecaminoso. El español capta esta división moral de manera notable: «anhelar/desear» para el anhelo justo frente a «codiciar» para la codicia, reflejando todo el rango semántico del griego.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1938', 'spa', 'el que desea, el que codicia', 'Sustantivo que designa a alguien que desea o anhela algo, con matiz potencialmente neutro o negativo. En 1 Corintios 10:6, Pablo advierte a los creyentes que no sean «codiciadores (ἐπιθυμητάς) de cosas malas» como lo fueron los israelitas en el desierto. El término puede describir un anhelo legítimo, pero aquí señala un deseo ilícito: la codicia de lo que Dios prohíbe. Pablo usa la historia de Israel como advertencia contra la avaricia y la concupiscencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1939', 'spa', 'Deseo, codicia o anhelo; generalmente concupiscencia pecaminosa, pero ocasionalmente un anhelo positivo e intenso.', 'Deseo, codicia o anhelo; generalmente concupiscencia pecaminosa, pero ocasionalmente un anhelo positivo e intenso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1940', 'spa', 'sentar sobre, colocar encima, montar', 'Verbo que significa colocar a alguien o algo sobre otra cosa, sentar o montar. En Mateo 21:7 se describe cómo los discípulos pusieron sus mantos sobre el pollino, y Jesús «se sentó (ἐπεκάθισεν) sobre ellos». El verbo capta la acción de montar o tomar asiento sobre algo. Este gesto cumple la profecía de Zacarías sobre el rey que viene humilde, montado sobre un asno, señalando paz en lugar de conquista militar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1941', 'spa', 'Invocar o clamar a Dios; ser llamado o apodado (en voz pasiva); apelar a una autoridad judicial.', 'Invocar o clamar a Dios; ser llamado o apodado (en voz pasiva); apelar a una autoridad judicial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1942', 'spa', 'cobertura, velo, pretexto (literal o figurado)', 'Sustantivo que significa una cubierta, velo o manto que oculta. En 1 Pedro 2:16, se advierte a los creyentes que no usen la libertad como «cobertura (ἐπικάλυμμα) para el mal», sino que vivan como siervos de Dios. La metáfora sugiere usar la libertad como pretexto o disfraz para el pecado. En el uso clásico, incluía coberturas físicas y, en Menandro, la idea de que la riqueza encubre muchos males. Pedro advierte contra abusar de la libertad cristiana como camuflaje para la maldad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1943', 'spa', 'cubrir, velar, ocultar', 'Verbo que significa cubrir o velar, usado literalmente para la nieve que cubre huellas o metafóricamente para ocultar hechos u oscurecer el entendimiento. En Romanos 4:7 se cita el Salmo 32:1: «Bienaventurados aquellos cuyas iniquidades son perdonadas y cuyos pecados son cubiertos (ἐπεκαλύφθησαν)». La forma pasiva sugiere la acción de Dios de ocultar o apartar los pecados de su vista. Este es el lenguaje de la expiación: pecados escondidos por la misericordia divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1944', 'spa', 'Maldito, bajo maldición; sujeto a maldición divina o condenación', 'Este fuerte adjetivo describe a alguien o algo que está bajo maldición, particularmente condenación divina. Aparece en contextos de separación de la bendición de Dios y exposición al juicio. En Juan 7:49 los fariseos desprecian al pueblo común llamándolo «maldito», mientras que el uso de Pablo en Gálatas (3:10, 13) vincula este término con la maldición de la ley que Cristo llevó en la cruz para redimirnos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1945', 'spa', 'Yacer sobre, estar puesto encima (física u obligatoriamente); presionar, agolparse, apremiar con insistencia.', 'El verbo ἐπίκειμαι (literalmente ''yacer sobre'') funciona como pasivo virtual de ἐπιτίθημι (''poner sobre'') y abarca dos polos de experiencia en el Nuevo Testamento. En su sentido estativo, describe cosas que yacen o están puestas sobre algo: una piedra ''estaba puesta'' sobre el sepulcro de Lázaro (Jn 11:38), pescado ''puesto sobre'' brasas recibe a los discípulos junto al mar de Tiberias (Jn 21:9), y regulaciones ''impuestas'' a los adoradores del antiguo pacto hasta el nuevo orden (Heb 9:10). Pablo lo usa figuradamente de la necesidad que le ''es impuesta'' de predicar el evangelio (1 Co 9:16). Pero en tres pasajes lucanos, ἐπίκειμαι adquiere fuerza activa y apremiante: la multitud ''agolpándose'' sobre Jesús para oír la palabra de Dios (Lc 5:1), los principales sacerdotes ''apremiando'' a Pilato con sus voces (Lc 23:23), y la tempestad ''cargando'' sobre los náufragos hasta perder toda esperanza (Hch 27:20).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1946', 'spa', 'Epicureo (seguidor de Epicuro)', 'Adjetivo propio que designa a los seguidores del filósofo Epicuro, quien enseñaba que el placer, entendido como tranquilidad y ausencia de dolor, constituye el bien supremo. En Hechos 17:18, filósofos epicúreos encuentran a Pablo en Atenas. Junto con los estoicos, debaten con él y lo llevan al Areópago. Los epicúreos eran materialistas que negaban la providencia divina y la vida después de la muerte, posturas radicalmente opuestas al mensaje paulino de resurrección y juicio divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1947', 'spa', 'auxilio, ayuda, asistencia', 'Sustantivo que significa ayuda, auxilio o apoyo. En Hechos 26:22, Pablo declara: «Habiendo obtenido auxilio (ἐπικουρίας) de Dios, persevero hasta el día de hoy dando testimonio a pequeños y grandes.» En el uso clásico podía referirse a refuerzos militares, pero aquí denota el respaldo y la protección divina. Pablo atribuye su supervivencia y su ministerio continuo no a su propia fuerza sino al socorro sustentador de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1948', 'spa', 'decidir, determinar, pronunciar sentencia', 'Verbo que significa decidir, juzgar o emitir un veredicto. En Lucas 23:24 se registra la decisión de Pilato: «Pilato sentenció (ἐπέκρινεν) que se cumpliera la petición de ellos.» Tras los insistentes clamores de la multitud exigiendo la liberación de Barrabás y la crucifixión de Jesús, Pilato pronuncia el juicio decisivo. El verbo marca el acto formal de dictar sentencia, cediendo Pilato ante la presión y condenando a un hombre inocente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1949', 'spa', 'Agarrar, asir: tomar físicamente a una persona (a menudo para sanar o arrestar); atrapar con palabras (hostilmente); echar mano espiritualmente. El ve', 'Agarrar, asir: tomar físicamente a una persona (a menudo para sanar o arrestar); atrapar con palabras (hostilmente); echar mano espiritualmente. El verbo griego ἐπιλαμβάνομαι evoca una mano que se extiende y agarra, ya sea con misericordia, hostilidad o fe. En los Evangelios describe con mayor frecuencia a Jesús tomando físicamente a alguien para sanar o rescatar: agarrando la mano de Pedro mientras se hunde (Mateo 14:31), tomando a un ciego de la mano (Marcos 8:23) o asiendo a un enfermo para curarlo en sábado (Lucas 14:4). Pero el mismo verbo también sirve a adversarios que intentan «atrapar» a Jesús en sus palabras (Lucas 20:20, 26), y Pablo lo eleva al ámbito espiritual cuando exhorta a los oyentes de Timoteo a «echar mano de la vida eterna» (1 Timoteo 6:19).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1950', 'spa', 'Olvidar o perder de la memoria; descuidar o desatender por falta de recuerdo.', 'Verbo deponente en voz media (ἐπιλανθάνομαι) formado de ἐπί + λανθάνω, que intensifica la noción básica de olvidar. En los Evangelios describe el vergonzoso descuido de los discípulos al no traer pan (Mt 16:5; Mc 8:14), mientras que Pablo lo transforma en una disciplina espiritual deliberada: ''olvidando lo que queda atrás'' en su carrera hacia el premio (Fil 3:13). La memoria de Dios se presenta como contraste enfático: él jamás olvidará las obras hechas por amor (Heb 6:10). El español ''olvidar'' captura esa misma doble dimensión del olvido involuntario y la desatención voluntaria.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1952', 'spa', 'faltar, agotarse, quedarse corto', 'Verbo que significa faltar, agotarse o resultar insuficiente. En Hebreos 11:32 se emplea retóricamente: «Me faltará (ἐπιλείψει) el tiempo si cuento de Gedeón, Barac, Sansón...» El autor señala que podría continuar enumerando héroes de la fe pero carece de tiempo suficiente. En el uso clásico incluía el agotamiento de recursos o el quedarse corto respecto a expectativas. Aquí marca el límite del espacio narrativo, no la escasez de figuras ejemplares.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1953', 'spa', 'olvido, estado de olvidar', 'Sustantivo que denota el estado o la condición de olvidar. Santiago 1:25 contrasta al oidor olvidadizo con el hacedor: aquel que mira en la ley perfecta de la libertad y persevera en ella, «no siendo oidor de olvido (ἐπιλησμονῆς)» sino hacedor de la obra. El genitivo describe a una persona caracterizada por el olvido, alguien que escucha la palabra pero inmediatamente la pierde de la memoria, sin llegar a ponerla en práctica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1954', 'spa', 'restante, sobrante, aún por venir', 'Adjetivo que significa restante, sobrante o todavía futuro. En 1 Pedro 4:2, los creyentes deben vivir «el tiempo restante (ἐπίλοιπον) en la carne ya no para las pasiones humanas, sino para la voluntad de Dios». El término señala lo que queda de la vida terrenal, el tiempo que aún falta por vivir. Pedro insta a reorientar los días restantes, dejando atrás la autocomplacencia para abrazar la obediencia, usando el sufrimiento pasado como catalizador de prioridades transformadas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1955', 'spa', 'explicación, interpretación, solución', 'Sustantivo que significa interpretación, explicación o solución, derivado de ἐπιλύω (resolver o explicar). En 2 Pedro 1:20, el autor advierte que «ninguna profecía de la Escritura proviene de interpretación (ἐπιλύσεως) privada». Este versículo debatido puede significar que los profetas no originaron sus mensajes por cuenta propia, o que los lectores no deben interpretar la Escritura según su propio capricho. El contexto favorece lo primero: la profecía surge del Espíritu Santo, no de invención humana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1957', 'spa', 'dar testimonio, testificar, confirmar', 'Verbo compuesto que significa dar testimonio, testificar en apoyo o confirmar una evidencia. En 1 Pedro 5:12, Pedro escribe: «Os he escrito brevemente, exhortando y testificando (ἐπιμαρτυρῶν) que esta es la verdadera gracia de Dios». El verbo sugiere añadir una confirmación autoritativa o testimonio a una declaración. El testimonio de Pedro autentica el mensaje del evangelio como gracia divina genuina, no como invención humana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1958', 'spa', 'cuidado, atención, supervisión diligente', 'Sustantivo que denota cuidado, atención o supervisión diligente. Hechos 27:3 relata que Julio el centurión trató a Pablo con amabilidad y le permitió ir a sus amigos «para recibir cuidado (ἐπιμελείας)». El uso clásico incluía tratamiento médico, atención a deberes cívicos o el esmero dedicado a cualquier asunto que requiriese diligencia. Aquí sugiere que los amigos proveyeron las necesidades de Pablo —alimento, atención médica, consuelo— durante el viaje a Roma.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1959', 'spa', 'cuidar, atender; encargarse de alguien o algo con diligencia y esmero', 'Este verbo en voz media significa cuidar de alguien, hacerse cargo de algo o administrar con diligencia. En el uso clásico incluye asumir responsabilidad sobre asuntos o ejercer supervisión. En el Nuevo Testamento aparece exclusivamente en contextos de atención práctica: el cuidado que el buen samaritano brinda al hombre herido (Lucas 10:34-35) y los requisitos para el liderazgo eclesial respecto a la administración familiar (1 Timoteo 3:5).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1960', 'spa', 'cuidadosamente, con atención y diligencia', 'Adverbio que describe una acción realizada con atención esmerada y minuciosidad. En Lucas 15:8, la mujer que busca su moneda perdida lo hace cuidadosamente, barriendo con diligencia toda su casa. La evidencia multilingüe (español «cuidadosamente», francés «soigneusement») enfatiza de manera consistente la cualidad deliberada y atenta de la acción. El griego clásico empleaba esta palabra para la precisión médica y la exactitud filosófica, mostrando cómo la observación cuidadosa se valoraba tanto en lo práctico como en lo intelectual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1961', 'spa', 'Permanecer en un lugar o persistir en un estado; quedarse, continuar o perseverar en una actividad o condición. Compuesto de ἐπί («sobre») y μένω («pe', 'Permanecer en un lugar o persistir en un estado; quedarse, continuar o perseverar en una actividad o condición. Compuesto de ἐπί («sobre») y μένω («permanecer»), este verbo añade un matiz de duración o insistencia al simple quedarse. En contextos narrativos significa demorarse en un lugar: Pablo quedándose en Corinto, los discípulos permaneciendo en Tiro (Hechos 21:4; 28:12). En contextos epistolares y teológicos cambia a persistir en un curso de acción o estado moral: «¿Perseveraremos en el pecado?» (Romanos 6:1). El español separa útilmente «permanecer» (permanencia espacial) de «continuar» (persistencia en curso), trazando el límite semántico entre presencia física y resolución moral.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1962', 'spa', 'consentir, asentir con la cabeza, dar aprobación, acceder a algo', 'Este verbo describía originalmente el gesto físico de inclinar la cabeza para señalar acuerdo o aprobación, usado frecuentemente en Homero para el asentimiento de Zeus. En tiempos del Nuevo Testamento adquirió el sentido más amplio de consentir o acceder a una petición. En Hechos 18:20, cuando los judíos de Éfeso piden a Pablo que se quede más tiempo, la cuestión es si él dio su consentimiento a la solicitud. Las glosas multilingües (español consintió, francés consentir) preservan la idea central de otorgar permiso o manifestar acuerdo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1963', 'spa', 'pensamiento, intención, propósito, concepción mental', 'Este sustantivo designa lo que pasa por la mente: un pensamiento, una noción o un propósito. En Hechos 8:22, Pedro confronta a Simón el Mago acerca de la intención de su corazón, el pensamiento subyacente que motivaba su deseo de comprar el poder del Espíritu. El griego clásico empleaba esta palabra para el pensamiento inventivo y la concepción creativa, pero también para propósitos e intenciones oscuras. La evidencia multilingüe muestra su rango semántico: el español pensamiento sugiere una reflexión general, mientras que el inglés intent y la clasificación de dominio apuntan hacia una actividad mental deliberada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1964', 'spa', 'jurar en falso, quebrantar un juramento, cometer perjurio', 'Este verbo significa jurar en falso o perjurarse: hacer un juramento sin intención de cumplirlo, o quebrantar una promesa sagrada. Jesús lo emplea en Mateo 5:33 al enseñar sobre los juramentos, contrastando el cumplimiento fiel de lo jurado con el perjurio. En Homero, los personajes juraban por los dioses con promesas solemnes; este verbo describe la violación de tales compromisos sagrados. Las glosas multilingües (español perjurarás, francés se parjurer) identifican unánimemente esto como perjurio, reflejando el reconocimiento transcultural de la ruptura de juramentos como una falta moral grave.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1965', 'spa', 'perjuro, que quebranta juramentos, que jura en falso', 'Este adjetivo describe a alguien que ha quebrantado su juramento o ha jurado en falso: un perjuro. Aparece en 1 Timoteo 1:10 dentro de un catálogo de vicios que enumera a quienes violan la ley de Dios. La palabra podía describir tanto el juramento en sí (como en Homero: un juramento falso) como a la persona que lo pronuncia (el perjuro). La evidencia multilingüe identifica unánimemente esto como referencia a los perjuros: personas caracterizadas por el quebrantamiento de juramentos. En la cultura griega, donde los juramentos por los dioses tenían un peso sagrado, el perjurio se consideraba moralmente reprobable y potencialmente peligroso, pues invitaba la retribución divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1966', 'spa', 'El día siguiente, al día siguiente; usado para sucesión temporal, especialmente en los relatos de viaje en Hechos.', 'Forma participial de ἔπειμι (''sobrevenir'') usada casi exclusivamente en sentido temporal como ''el día siguiente'' o ''al otro día''. Las cinco apariciones en el NT se encuentran en Hechos, marcando los viajes misioneros de Pablo y transiciones narrativas clave. El español ''día siguiente'' refleja con precisión este significado temporal. Lucas lo emplea como bisagra narrativa — señalando el día en que Moisés regresó y encontró a israelitas disputando (Hch 7:26), y puntuando el itinerario de Pablo de isla en isla por el Egeo (Hch 16:11; 20:15).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1968', 'spa', 'Un verbo vívido que describe un descenso repentino y enérgico sobre una persona. Con mayor frecuencia en Hechos, el Espíritu Santo ''cae sobre'' los cre', 'Un verbo vívido que describe un descenso repentino y enérgico sobre una persona. Con mayor frecuencia en Hechos, el Espíritu Santo ''cae sobre'' los creyentes en momentos decisivos: en la casa de Cornelio (Hch 10:44), sobre los creyentes samaritanos (Hch 8:16) y sobre los discípulos de Éfeso (Hch 19:17). El temor igualmente ''cae sobre'' Zacarías ante la aparición del ángel (Lc 1:12). Sin embargo, el mismo verbo captura momentos profundamente humanos: el padre echándose sobre el cuello del hijo pródigo en un abrazo (Lc 15:20), Pablo arrojándose sobre Eutico (Hch 20:10), y los ancianos de Éfeso llorando sobre el cuello de Pablo (Hch 20:37). En Mr 3:10, las multitudes se abalanzan sobre Jesús para tocarlo, mostrando el matiz agresivo de esta palabra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1969', 'spa', 'reprender severamente, amonestar, golpear con palabras', 'Este verbo significa golpear o pegar, pero en la mayor parte del uso clásico y neotestamentario se refiere a golpear con palabras: reprender, reprochar o corregir a alguien con severidad. En 1 Timoteo 5:1, Pablo instruye a Timoteo a no reprender duramente a un hombre mayor, sino a exhortarlo con gentileza como a un padre. El sentido físico de golpear (como con un arco en Homero) dio paso al sentido metafórico de reprensión verbal. La evidencia multilingüe (español reprendas, alemán zurechtweisen) capta tanto la aspereza como la intención correctiva de tal reprensión.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1970', 'spa', 'ahogar, estrangular, sofocar; asfixiar o suprimir la respiración', 'Verbo vívido que significa ahogar, estrangular o sofocar. Los escritores médicos lo usan para describir a un doctor que administra pociones amargas que provocan arcadas en los pacientes. En textos agrícolas se refiere a las malezas que ahogan los cultivos de grano. En voz pasiva significa ''ser ahogado'' o sofocado. En los Evangelios aparece de manera célebre en la parábola del sembrador, donde los espinos ahogan la semilla que crece. El verbo simple es menos frecuente que su forma compuesta ἀποπνίγω, pero ambos transmiten la misma imagen contundente del aliento cortado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1971', 'spa', 'Anhelar intensamente, desear con ardor; un anhelo profundo y sostenido del corazón.', 'Forma intensificada de ποθέω (desear), donde el prefijo ἐπι- profundiza el deseo hasta convertirlo en un anhelo que duele. Pablo la emplea repetidamente para expresar la angustia pastoral de la separación: anhelando ver a los romanos (Ro 1:11), gimiendo por la morada celestial (2 Co 5:2), añorando a los filipenses con el afecto mismo de Cristo (Fil 1:8). El español «anhelo» capta bien esa intensidad visceral. No se trata de un deseo pasajero, sino del tirón profundo del amor que atraviesa la distancia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1973', 'spa', 'anhelado, deseado, amado; objeto de profundo afecto y anhelo', 'Este adjetivo describe a alguien o algo que es ardientemente deseado o anhelado, una persona amada o un objeto apreciado. Pablo lo emplea en Filipenses 4:1 para dirigirse a los creyentes filipenses como su gozo y corona anhelados, expresando un afecto profundo y un deseo ferviente de reencontrarse. La palabra capta la intensidad del deseo que surge de la separación o la ausencia. Las glosas multilingues confirman este matiz: el español anhelados transmite anhelo profundo, mientras que el inglés longed-for sugiere un deseo persistente a través de la distancia. En el Nuevo Testamento, el uso enfatiza la dimensión afectuosa más que el sentido clásico de echar en falta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1974', 'spa', 'anhelo, deseo ferviente; estado de añoranza persistente', 'Este sustantivo designa el estado o la experiencia de anhelar: un deseo ferviente y persistente por alguien o algo. En Romanos 15:23, Pablo habla de su anhelo de visitar a los cristianos romanos, un deseo que ha albergado durante muchos años. Está estrechamente vinculado a las formas verbales y adjetivales que expresan deseo y añoranza. La evidencia multilingüe muestra matices variados: el español anhelo sugiere un deseo profundo, el francés désir es más general y el alemán Verlangen implica un deseo intenso. Esto refleja el rango semántico que va desde un simple querer hasta un anhelo apasionado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1975', 'spa', 'ir hacia, viajar con rumbo a, acudir, congregarse', 'Este verbo describe el acto de viajar hacia un lugar o dirigirse a un destino. En Lucas 8:4, las multitudes acuden a Jesús desde diversas ciudades, convergiendo para escuchar su enseñanza. En el uso clásico incluía tanto el viaje literal como el recorrido metafórico (como un pensamiento que atraviesa la mente). La Septuaginta lo empleaba para presentarse ante una asamblea. La evidencia multilingüe revela variación interpretativa: el español que-acudían enfatiza la convergencia, mientras que el francés venir se centra en la acción de venir, lo que indica que los traductores entendieron esto como multitudes que confluían hacia Jesús, no que simplemente pasaban de largo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1976', 'spa', 'coser encima, remendar; fijar un parche cosiendo sobre una tela', 'Este verbo significa coser algo sobre otra cosa, es decir, fijar o remendar un trozo de tela sobre una prenda. Jesús lo utiliza en Marcos 2:21 en su parábola sobre no coser un remiendo de tela nueva sobre un vestido viejo, ilustrando la incompatibilidad entre las formas del antiguo y del nuevo pacto. La imagen es práctica y doméstica: todos en el mundo antiguo comprendían que la tela nueva encogería y se separaría del tejido viejo. Las glosas multilingüísticas (español cose, francés coudre, alemán aufnähen) captan la acción básica de coser, y el alemán preserva específicamente el sentido de ''coser encima''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1979', 'spa', 'provisiones, bastimentos; víveres para un viaje o almacenados para necesidades futuras', 'Este sustantivo se refiere a provisiones o víveres, especialmente los reunidos para un viaje o almacenados para necesidades futuras. En Lucas 9:12, los discípulos sugieren que Jesús despida a las multitudes para que puedan encontrar comida y alojamiento en las aldeas cercanas; la palabra designa las provisiones necesarias para sustentar a la muchedumbre. En el uso clásico podía referirse tanto a la acción de buscar abastecimiento como al propio acopio. La evidencia multilingüe es notablemente uniforme: provisions, provisiones, Proviant, lo que muestra un reconocimiento universal de este término como raciones de viaje o reservas alimenticias.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1980', 'spa', 'Visitar con cuidado o interés (Dios visitando a su pueblo, creyentes visitando a los enfermos); seleccionar mediante inspección. El verbo griego ἐπισκ', 'Visitar con cuidado o interés (Dios visitando a su pueblo, creyentes visitando a los enfermos); seleccionar mediante inspección. El verbo griego ἐπισκέπτομαι (emparentado con ἐπίσκοπος, ''supervisor'') significa mirar a alguien con atención deliberada. En la mayoría de los casos, Dios o los seres humanos visitan a quienes están en necesidad: Dios ''visitó y redimió a su pueblo'' (Lucas 1:68), las multitudes reconocen que ''Dios ha visitado a su pueblo'' (Lucas 7:16), y el Hijo del Hombre juzga según quién visitó a los enfermos y encarcelados (Mateo 25:36, 43). En español visitar, en francés visiter y en alemán besuchen todos convergen en este sentido pastoral. Pero en Hechos 6:3 la palabra gira hacia el significado de ''seleccionar'': los apóstoles dicen a la comunidad que ''busquen y elijan'' a siete hombres para el servicio, apoyándose en el significado raíz de inspección cuidadosa que subyace a ambos sentidos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1981', 'spa', 'morar sobre, reposar sobre, cubrir con sombra protectora', 'Este verbo combina las ideas de habitar y cubrir con sombra: establecerse sobre algo o reposar sobre ello de manera protectora o fortalecedora. Pablo lo usa metafóricamente en 2 Corintios 12:9, donde el poder de Cristo morará sobre él o lo cubrirá. El sentido clásico se refería al alojamiento militar en casas particulares, pero el uso neotestamentario es figurado: el poder divino estableciendo su morada en la debilidad humana. La evidencia multilingüe muestra una variedad interpretativa: el español reposo, el francés habiter (habitar) y el alemán sich-niederlassen (establecerse), todos capturando la idea de una presencia que permanece.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1982', 'spa', 'Cubrir con sombra, hacer sombra sobre; usado de la presencia divina que envuelve o cubre con poder y protección.', 'Significa literalmente proyectar una sombra sobre algo, pero en el NT adquiere un peso teológico profundo. En la Transfiguración, la nube de la gloria de Dios cubre con su sombra a los discípulos (Matt 17:5; Mark 9:7; Luke 9:34). De manera aún más significativa, el ángel le dice a María que el poder del Altísimo la cubrirá con su sombra (Luke 1:35), evocando la gloria de la Shekiná que se cernía sobre el tabernáculo. Incluso la sombra sanadora de Pedro en Acts 5:15 recurre a esta misma imagen. El término conserva tanto el sentido literal de sombra como la connotación de cobertura divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1984', 'spa', 'visitación (inspección o juicio divino); cargo de supervisor, obispado', 'Derivado de ἐπίσκοπος (''supervisor, obispo''), este sustantivo posee dos sentidos bien diferenciados en el NT. En Lucas 19:44 y 1 Pedro 2:12 designa la ''visitación'' de Dios, ese momento en que él se acerca para juzgar o mostrar misericordia. En Hechos 1:20 (citando el Salmo 109:8) y 1 Timoteo 3:1, se refiere al cargo u oficio de supervisor en la iglesia primitiva. Esta doble acepción tiende un puente entre el concepto teológico de Dios visitando a su pueblo y la realidad práctica del liderazgo eclesial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1985', 'spa', 'Supervisor, obispo, guardián; quien vela por una comunidad y la dirige, aplicado a líderes eclesiales y a Cristo mismo.', 'Originalmente significaba ''el que vigila'' o ''guardián'', y fue adoptado por la iglesia primitiva para designar a los líderes responsables de pastorear las congregaciones. Pablo se dirige a los obispos de Filipos (Phil 1:1), encarga a los ancianos de Éfeso que cuiden de su rebaño como supervisores (Acts 20:28) y establece los requisitos para el cargo (1 Tim 3:2; Titus 1:7). Pedro aplica notablemente este título a Cristo mismo como ''el Obispo de vuestras almas'' (1 Pet 2:25). La palabra española ''obispo'' desciende directamente de este término griego, mostrando cómo un vocablo funcional se convirtió en título eclesiástico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1986', 'spa', 'estirar sobre, retraer, borrar la circuncisión', 'Este verbo significa estirar o jalar algo sobre otra cosa. En 1 Corintios 7:18, tiene un significado médico y cultural específico: jalar el prepucio hacia adelante para ocultar las marcas de la circuncisión, una práctica conocida como epispasmo. Algunos judíos helenizados se sometían a procedimientos quirúrgicos para revertir la circuncisión y parecer incircuncisos en los gimnasios griegos. El argumento de Pablo es que nadie debe intentar borrar las señales físicas de su condición pactual. La evidencia multilingüe muestra que la mayoría de los traductores captan este significado específico: el español ''se-haga-incircunciso'', aunque el inglés ''let-him-become-uncircumcised'' es más interpretativo que literal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1987', 'spa', 'Verbo en voz media que expresa un conocimiento basado en la competencia y la familiaridad más que en la cognición abstracta. A diferencia de γινώσκω (', 'Verbo en voz media que expresa un conocimiento basado en la competencia y la familiaridad más que en la cognición abstracta. A diferencia de γινώσκω (conocimiento relacional) u οἶδα (percepción intuitiva), ἐπίσταμαι conlleva matices de conocimiento experto y vivencial — la escalofriante declaración del demonio ''a Jesús conozco (γινώσκω) y de Pablo sé (ἐπίσταμαι)'' en Hechos 19:15 revela su matiz de reconocer el poder probado de alguien. Aparece frecuentemente en Hechos para conocimiento práctico: Apolos conocía el bautismo de Juan (Hch 18:25), Cornelio conocía las costumbres judías (Hch 10:28) y los artesanos sabían que su oficio estaba en riesgo (Hch 19:25).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1988', 'spa', 'Maestro, supervisor, jefe; tratamiento respetuoso hacia quien tiene autoridad, usado exclusivamente en Lucas como título para Jesús.', 'Título de tratamiento que significa ''maestro'' o ''supervisor'', empleado exclusivamente en el Evangelio de Lucas como forma en que los discípulos se dirigen a Jesús. Mientras Mateo y Marcos usan ''Rabí'' o ''Maestro'' en los pasajes paralelos, Lucas escoge consistentemente ἐπιστάτης, un término tomado de la vida cívica griega donde designaba a un supervisor, superintendente o comandante. Pedro se dirige así a Jesús cuando es llamado a echar las redes (Lc 5:5), los discípulos claman a él durante la tempestad (Lc 8:24), y Pedro lo usa en la Transfiguración (Lc 9:33). La palabra enfatiza la autoridad y la supervisión más que la mera instrucción, reflejando un matiz que va más allá de ''maestro'' como simple enseñante.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1989', 'spa', 'escribir a, enviar palabra; comunicar por carta, especialmente instrucciones oficiales', 'Este verbo significa enviar un mensaje o escribir a alguien, especialmente por medio de una carta. En el uso clásico abarca enviar noticias, dar órdenes o comunicar mandatos por escrito. En el Nuevo Testamento aparece en contextos de comunicación apostólica oficial: la carta del Concilio de Jerusalén a los creyentes gentiles (Hechos 15:20; 21:25) y la referencia del autor de Hebreos a su propia epístola (Hebreos 13:22). El término conlleva un sentido de instrucción escrita con autoridad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1990', 'spa', 'entendido, conocedor, hábil, experto', 'Este adjetivo describe a alguien que posee conocimiento y comprensión: un experto, una persona hábil, alguien versado en un área determinada. En Santiago 3:13, aparece en la pregunta ''¿Quién es sabio y entendido entre vosotros?'', colocando la sabiduría en paralelo con la pericia o destreza. El uso clásico enfatizaba tanto el conocimiento teórico como la habilidad práctica: estar versado en navegación, ser conocedor de un oficio o diestro en el consejo. La evidencia multilingüe (español entendido, alemán verständig) subraya consistentemente la dimensión intelectual: la comprensión como capacidad mental y no como mera acumulación de información.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1991', 'spa', 'fortalecer, establecer firmemente; confirmar o afianzar la fe de alguien', 'Compuesto de ἐπί (''sobre'') y στηρίζω (''fijar, establecer''), este verbo significa fortalecer o confirmar, y aparece exclusivamente en Hechos en el contexto de los viajes misioneros de Pablo. Tras proclamar el evangelio, Pablo y Bernabé regresan a las iglesias recién fundadas ''fortaleciendo las almas de los discípulos'' (Hch 14:22). Judas y Silas, de igual modo, ''fortalecieron'' a los creyentes en Antioquía (15:32). El verbo no describe la conversión inicial, sino la labor crucial de seguimiento que afianza a los creyentes en su fe.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1992', 'spa', 'carta, epístola — comunicación escrita enviada a destinatarios, especialmente las cartas apostólicas a las iglesias', 'carta, epístola — comunicación escrita enviada a destinatarios, especialmente las cartas apostólicas a las iglesias');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1993', 'spa', 'silenciar, tapar la boca, amordazar', 'Este verbo significa literalmente poner algo sobre la boca: embridar, amordazar o silenciar. En Tito 1:11, Pablo dice que a los falsos maestros hay que taparles la boca, silenciarlos. El uso clásico incluía embridar caballos y frenar enemigos, pero también el sentido técnico de un flautista colocándose la embocadura. El sentido metafórico de silenciar a un orador estaba bien establecido. La evidencia multilingüe subraya fuertemente la función de silenciamiento: el español ''tapar-la-boca'', el francés y el alemán con expresiones igualmente directas. Es un lenguaje enérgico sobre detener el discurso destructivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1994', 'spa', 'Volverse, regresar, retornar; abarca el giro fisico, el arrepentimiento espiritual y el hacer que otros se vuelvan.', 'Volverse, regresar, retornar; abarca el giro fisico, el arrepentimiento espiritual y el hacer que otros se vuelvan.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1995', 'spa', 'giro, conversión, arrepentimiento', 'Este sustantivo denota un giro o cambio de dirección, una reorientación. En Hechos 15:3, describe la conversión de los gentiles, su volverse de los ídolos hacia Dios. El griego clásico usaba esta palabra para barcos que viraban, soldados que giraban en formación o ríos que serpenteaban. El Nuevo Testamento se apropia de este lenguaje espacial para expresar la reorientación espiritual. La evidencia multilingüe muestra opciones interpretativas: el español conversión y el francés conversion explicitan el sentido teológico, mientras que el término griego en sí es más neutro: simplemente un giro que el contexto convierte en espiritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1996', 'spa', 'Congregar, reunir; juntar personas dispersas en un solo grupo (en voz activa y pasiva).', 'Verbo compuesto (ἐπι + συν + ἄγω) que transmite la acción deliberada de reunir a individuos dispersos en un grupo unificado. Jesús mismo lo usa en la conmovedora imagen de la gallina que recoge a sus polluelos bajo las alas (Mt 23:37; Lc 13:34), y describe la congregación escatológica cuando el Hijo del Hombre envíe a sus ángeles a reunir a los elegidos de los cuatro vientos (Mt 24:31; Mr 13:27). En voz pasiva, retrata a multitudes apiñándose alrededor de Jesús (Mr 1:33) y a naciones congregadas ante el trono del juicio (Mt 25:32). El español «reunir» capta bien ese impulso de volver a juntar lo disperso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1998', 'spa', 'correr juntos, congregarse rápidamente, converger con urgencia', 'Este verbo describe a personas corriendo juntas hacia un lugar, convergiendo rápidamente, a menudo en respuesta a algún evento o espectáculo. En Mark 9:25, Jesús ve a una multitud corriendo hacia donde él está lidiando con un muchacho endemoniado. El prefijo ἐπι- intensifica el sentido básico de ''correr juntos'', sugiriendo una convergencia urgente. La evidencia multilingüe capta tanto el movimiento como la reunión: el español ''se-reunía-corriendo'', el francés accourir (acudir corriendo), el alemán zusammenlaufen (correr juntos). La imagen es de personas apresurándose desde múltiples direcciones hacia un mismo punto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2000', 'spa', 'peligroso, precario, arriesgado', 'Este adjetivo describe algo propenso a caer, inestable o peligroso: una situación precaria o una condición riesgosa. En Acts 27:9, la navegación se ha vuelto peligrosa porque la estación avanza hacia las tormentas invernales. En el uso clásico se aplicaba a cualquier cosa inestable: posiciones políticas precarias, cosas poco confiables, enfermedades peligrosas o proposiciones dudosas. La evidencia multilingüe es notablemente uniforme: dangerous, peligrosa, dangereux, mostrando un reconocimiento universal del riesgo y el peligro. El uso médico para enfermedades graves sugiere condiciones que amenazan la vida, lo cual encaja con el relato del viaje de Pablo donde las vidas efectivamente están en juego.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2001', 'spa', 'insistir con urgencia, hacerse más fuerte, presionar con vehemencia', 'Este verbo significa fortalecerse o prevalecer, y por extensión, insistir con urgencia o presionar un punto con fuerza. En Luke 23:5, los acusadores de Jesús están insistiendo, presionando sus cargos con urgencia ante Pilato. El significado básico involucra un aumento en fuerza o intensidad, pero en contexto describe el crescendo de la acusación: siguen insistiendo, volviéndose cada vez más vehementes. La evidencia multilingüe (español insistían, francés insister) capta la persistencia y urgencia de su alegato. Se trata de presionar un caso sin cesar, sin dar marcha atrás.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2002', 'spa', 'amontonar, acumular, apilar', 'Este verbo significa amontonar o apilar, acumular en grandes cantidades. En 2 Timothy 4:3, Pablo advierte que las personas amontonarán maestros según sus propios deseos, acumulando instructores que les digan lo que quieren oír. La imagen es de apilar o amasar una colección. El uso clásico incluía tanto el amontonamiento literal de objetos como la acumulación figurada de argumentos o autoridades. La evidencia multilingüe muestra variación en cómo los traductores manejan la metáfora: el español amontonarán preserva la imagen de apilar, mientras que el contexto deja claro que se trata de reunir múltiples maestros.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2003', 'spa', 'Mandato o directriz autoritativa, especialmente una orden divina o apostólica.', 'El sustantivo ἐπιταγή denota un mandato formal u orden autoritativa, derivado del verbo ἐπιτάσσω (''mandar sobre''). En el Nuevo Testamento aparece exclusivamente en las cartas de Pablo y en Tito, portando el peso de la autoridad divina o apostólica. Pablo distingue cuidadosamente entre lo que dice κατ᾽ ἐπιταγήν (''por mandato'', 1 Co 7:6) y lo que ofrece como consejo personal, revelando un sentido finamente calibrado de la palabra apostólica frente al mero consejo. En Tito 2:15 el término se extiende hacia la noción más amplia de autoridad delegada en sí misma.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2004', 'spa', 'Mandar, ordenar con autoridad — imponer una directiva desde una posición de poder sobre personas o espíritus. El verbo ἐπιτάσσω (epitasso), compuesto ', 'Mandar, ordenar con autoridad — imponer una directiva desde una posición de poder sobre personas o espíritus. El verbo ἐπιτάσσω (epitasso), compuesto de ἐπί (''sobre'') y τάσσω (''disponer, ordenar''), significa mandar u ordenar con autoridad reconocida. En los Evangelios Sinópticos caracteriza la autoridad soberana de Jesús: las multitudes se maravillan de que ''manda incluso a los espíritus inmundos, y le obedecen'' (Marcos 1:27; Lucas 4:36). Describe a Herodes ordenando a un soldado traer la cabeza de Juan (Marcos 6:27), a Jesús mandando a la multitud reclinarse (Marcos 6:39), y al sumo sacerdote ordenando que golpeen a Pablo (Hechos 23:2). Pablo afirma tener derecho a ''ordenar'' a Filemón, pero prefiere apelar en su lugar (Flm 1:8). El árabe يَأْمُرُ, el hebreo מְצַוֶּה, el coreano 명령하다 y el español mandar/ordenar reflejan todos un discurso directivo con autoridad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2005', 'spa', 'Completar, llevar a cumplimiento; ser realizado o perfeccionado (pasivo); llevar a cabo deberes sagrados. Un verbo de acción que denota completar y qu', 'Completar, llevar a cumplimiento; ser realizado o perfeccionado (pasivo); llevar a cabo deberes sagrados. Un verbo de acción que denota completar y que transita del taller al templo. Pablo lo usa para terminar la colecta para Jerusalén (2 Corintios 8:6, 11) y para describir a Dios completando la buena obra que comenzó en los creyentes (Filipenses 1:6), una promesa que ha alentado a incontables santos. La voz pasiva aparece en Gálatas 3:3, donde Pablo pregunta incisivamente si lo que el Espíritu comenzó puede ser ''completado'' por la carne. En contextos cultuales (Hebreos 9:6), describe a los sacerdotes realizando sus deberes rituales. El español distingue acertadamente entre ''completar'' para terminar una tarea y ''perfeccionar'' para el refinamiento sagrado, mientras que el alemán usa uniformemente vollenden, captando el énfasis constante de la palabra en llevar algo a su fin previsto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2006', 'spa', 'necesario, adecuado, indispensable, lo que se requiere', 'Este adjetivo describe lo que es necesario, adecuado o indispensable: aquello que se requiere para un propósito o que se ajusta a una situación. En James 2:16, se refiere a las necesidades corporales: alimento y vestido necesarios para la supervivencia diaria. El uso clásico enfatizaba la idoneidad para un propósito: un lugar adecuado para ejercicios de caballería, una persona apta para asociarse, o cosas merecedoras de cierto trato. La evidencia multilingüe muestra opciones interpretativas: el inglés ''necessary'' enfatiza el requisito, el español ''cosas-necesarias'' hace explícitas las necesidades prácticas. El término porta ambos sentidos: lo que es adecuado y lo que es indispensable.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2007', 'spa', 'Poner o colocar sobre; por extension, anadir, imponer o atacar.', 'Poner o colocar sobre; por extension, anadir, imponer o atacar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2008', 'spa', 'Reprender o censurar severamente con autoridad; en raras ocasiones, emitir una advertencia solemne o mandato', 'Reprender o censurar severamente con autoridad; en raras ocasiones, emitir una advertencia solemne o mandato');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2009', 'spa', 'castigo, pena, disciplina correctiva', 'Este sustantivo originalmente se refería a los plenos derechos cívicos en las ciudades griegas, pero evolucionó para designar castigo o pena, particularmente la disciplina correctiva. En 2 Corintios 2:6, Pablo alude al castigo impuesto por la mayoría de la iglesia sobre un ofensor, una disciplina orientada a la restauración. El desarrollo semántico de ''honor'' a ''castigo'' probablemente refleja la idea de sanciones que afectan la posición cívica de una persona. La evidencia multilingüe muestra este rango: reprensión, punition, Strafe, todos apuntando hacia la corrección disciplinaria.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2010', 'spa', 'Permitir, dar licencia: conceder autorización para que alguien actúe o proceda. ἐπιτρέπω significa permitir o autorizar, concediendo a alguien licenci', 'Permitir, dar licencia: conceder autorización para que alguien actúe o proceda. ἐπιτρέπω significa permitir o autorizar, concediendo a alguien licencia para hacer lo que solicita. Sus 18 apariciones en el Nuevo Testamento abarcan una amplia gama de situaciones sociales y espirituales donde la autoridad se ejerce otorgando o negando permiso. Jesús permite a los demonios gadarenos entrar en la piara de cerdos (Mateo 8:31; Marcos 5:13; Lucas 8:32), revelando simultáneamente su autoridad sobre los espíritus inmundos. El aspirante a discípulo pide «permíteme primero ir a enterrar a mi padre» (Mateo 8:21; Lucas 9:59, 61). Moisés «permitió» carta de divorcio por la dureza de corazón (Mateo 19:8; Marcos 10:4). Pablo lo usa para el orden congregacional (1 Corintios 14:34; 1 Timoteo 2:12). Pilato permite a José de Arimatea tomar el cuerpo de Jesús (Juan 19:38). Festo permite a Pablo hablar por sí mismo (Hechos 26:1; 27:3; 28:16).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2011', 'spa', 'comisión, autoridad, plenos poderes para actuar', 'Este sustantivo designa autoridad, comisión o plenos poderes para decidir y actuar. En Hechos 26:12, Pablo relata que viajaba a Damasco con la autoridad y comisión de los principales sacerdotes para arrestar a los cristianos. En el uso clásico se enfatizaba la referencia a un árbitro, poder de decisión o plenos poderes otorgados para una misión. El equivalente latino ''in fidem'' (rendición absoluta) capta la naturaleza integral de esta autoridad. La evidencia multilingüe muestra un rango coherente: commission, comisión, permission, todos apuntando a una autoridad delegada para actuar en nombre de otro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2012', 'spa', 'mayordomo, tutor, administrador; persona a quien se confía la supervisión de asuntos o personas', 'Este sustantivo designa a alguien a quien se le confía una mayordomía: un administrador del hogar, un supervisor de hacienda o un tutor de menores. En el uso clásico incluye albaceas, gobernadores y procuradores. En el Nuevo Testamento aparece en la parábola de Jesús sobre los obreros y su capataz (Mateo 20:8), en la conexión de Juana con la casa de Herodes (Lucas 8:3) y en la descripción paulina de los tutores que cuidan a los niños hasta su mayoría de edad (Gálatas 4:2).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2013', 'spa', 'Obtener, alcanzar, lograr; conseguir aquello que se busca o que ha sido prometido.', 'Conlleva el sentido básico de dar en el blanco o alcanzar con éxito una meta, extendiéndose a la idea de obtener o lograr algo deseado. Pablo lo emplea de manera incisiva en Rom 11:7 para describir la paradoja de Israel: la nación no obtuvo lo que buscaba, pero los elegidos sí lo alcanzaron. El autor de Hebreos celebra a Abraham, quien con paciencia ''alcanzó la promesa'' (Heb 6:15), y a los héroes de la fe que ''alcanzaron promesas'' (Heb 11:33). Santiago advierte que codiciar sin pedir a Dios lleva a no obtener (Jas 4:2).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2014', 'spa', 'aparecer, hacerse visible; resplandecer, brillar (de la luz o la gracia divina)', 'Formado por ἐπί (''sobre'') y φαίνω (''brillar, aparecer''), este verbo significa hacerse visible o resplandecer, y en el NT abarca tanto la manifestación física como la teológica. En Lucas 1:79, Zacarías profetiza que el Mesías ''alumbrará'' a los que están en tinieblas. En Hechos 27:20, ni el sol ni las estrellas ''aparecieron'' durante la tempestad. De modo aún más significativo, Tito 2:11 y 3:4 proclaman que la gracia y la bondad de Dios se han ''manifestado'' a toda la humanidad, término que dio origen al concepto teológico de ''epifanía''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2015', 'spa', 'Aparición, manifestación; despliegue visible de la presencia divina, usado del primer y segundo advenimiento de Cristo.', 'Sustantivo que denota una manifestación llamativa y visible, usado originalmente en el griego helenístico para la aparición dramática de una deidad o una visita real. En el NT pertenece exclusivamente a las Epístolas Pastorales y 2 Tesalonicenses, donde enmarca tanto la encarnación de Cristo como su retorno anticipado en gloria. Pablo habla de la gracia ''ahora manifestada por la aparición de nuestro Salvador'' (2 Ti 1:10) y también de ''su manifestación y su reino'' aún por venir (2 Ti 4:1). El término enfatiza tanto la visibilidad como la grandeza del evento, capturando la idea de un desvelamiento de lo que estaba oculto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2016', 'spa', 'glorioso, notable, distinguido, manifiesto', 'Este adjetivo describe lo que es conspicuo, notable o distinguido, aquello que sale a la luz y llama la atención. En Hechos 2:20, Pedro cita a Joel sobre el sol oscureciéndose antes del ''gran y glorioso día del Señor''. El uso clásico abarcaba desde dioses que aparecían para ayudar a los mortales, hasta rasgos geográficos prominentes y personas de alto rango. La palabra conlleva tanto visibilidad (manifiesto, evidente) como cualidad (glorioso, notable). La evidencia multilingüe muestra variación interpretativa: ''glorious'' enfatiza esplendor, manifiesto enfatiza visibilidad, remarquable destaca notabilidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2017', 'spa', 'brillar sobre, iluminar, dar luz', 'Este verbo significa brillar sobre algo o dar luz a alguien. En Efesios 5:14, Pablo cita lo que posiblemente sea un himno cristiano primitivo: ''Despierta, tú que duermes, y levántate de entre los muertos, y Cristo te alumbrará''. La imagen es la de una luz que amanece sobre quienes emergen de la oscuridad. La Septuaginta empleó este término para el sol que resplandece, y la forma pasiva sugiere una luz que irrumpe. La evidencia multilingüe es consistente: brillar sobre, iluminar, dar luz, todos enfatizando la fuente de iluminación actuando sobre un receptor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2019', 'spa', 'gritar, clamar, vociferar en respuesta a alguien o en contra de alguien', 'En el Nuevo Testamento, este verbo capta la energía visceral de una multitud que alza la voz, ya sea en aclamación o en protesta hostil. Durante el juicio de Jesús, la gente no dejaba de gritar pidiendo la crucifixión (Lc 23:21), mientras que en Hechos la multitud de Cesarea aclamó a Herodes con honores divinos (Hch 12:22). La fuerza pública y declamatoria de la palabra queda reflejada tanto en ''aclamaba'' como en ''gritaban'', y con frecuencia lleva una carga emocional que va más allá del habla corriente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2021', 'spa', 'intentar, emprender; poner mano a una empresa o tarea', 'Este verbo significa poner manos a la obra, intentar o emprender algo. El uso clásico enfatiza el inicio de un trabajo, la tentativa o el esfuerzo por lograr un objetivo. En el Nuevo Testamento aparece en contextos de empresas significativas: la cuidadosa composición del Evangelio de Lucas (Lucas 1:1), los oponentes que intentaron disputar con Esteban (Hechos 9:29) y los exorcistas judíos que pretendieron usar el nombre de Jesús (Hechos 19:13).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2022', 'spa', 'derramar sobre, verter encima', 'Este verbo significa derramar algo sobre otra cosa, verter un líquido sobre una superficie u objeto. En Lucas 10:34, el buen samaritano derrama aceite y vino sobre las heridas del hombre, un tratamiento médico habitual en la antigüedad. El uso clásico incluía tanto líquidos (agua, vino) como usos metafóricos (derramar sueño sobre alguien, verter lamentos sobre los muertos). El prefijo ἐπι- enfatiza la dimensión de ''sobre'': no se trata simplemente de verter sino de aplicar sobre algo específico. La evidencia multilingüe es directa: derramar sobre, verser sur, echando.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2023', 'spa', 'Proveer, suplir, suministrar generosamente; usado de la provisión de Dios y del cultivo activo de virtudes por los creyentes.', 'Originalmente un término de la vida cívica —un corego era quien financiaba generosamente un coro—, este verbo lleva connotaciones de provisión abundante y liberal. Pablo lo usa para referirse a Dios que suministra semilla al sembrador y multiplica la cosecha (2 Cor 9:10), y al Espíritu que es provisto mediante la fe (Gal 3:5). En Col 2:19, Cristo como Cabeza provee nutrición a todo el cuerpo. Pedro lo emplea memorablemente al exhortar a los creyentes a ''añadir'' a su fe virtud, conocimiento y amor (2 Pet 1:5), con la promesa de que la entrada al reino eterno les será ''abundantemente provista'' (2 Pet 1:11).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2026', 'spa', 'Edificar sobre un fundamento; erigir o construir sobre algo ya puesto, usado metafóricamente para el crecimiento espiritual.', 'Metáfora de construcción que significa edificar sobre un fundamento ya establecido. Cada aparición en el Nuevo Testamento es figurada: Pablo advierte a los corintios que, si bien él puso el fundamento de Cristo, cada constructor debe tener cuidado de cómo edifica sobre él, ya sea con oro, plata y piedras preciosas o con madera, heno y paja (1 Co 3:10-14). Efesios 2:20 declara que los creyentes están ''edificados sobre el fundamento de los apóstoles y profetas, siendo la piedra angular Cristo Jesús mismo''. Colosenses 2:7 habla de estar ''arraigados y sobreedificados en él''. No se trata de construir desde cero, sino de levantar sobre lo que Dios ya ha establecido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2027', 'spa', 'encallar, varar, hacer encallar un barco; naufragar al chocar contra tierra o un banco de arena', 'Este verbo marítimo describe la acción de hacer encallar una embarcación o naufragar al chocar contra la costa. Implica el impacto violento de un navío que golpea el fondo o un banco de arena, quedando atrapado e inmóvil. En Hechos 27:41, el barco de Pablo encalla en un banco de arena cerca de Malta, atrapado entre dos corrientes, con la proa clavada mientras la popa se deshace bajo el oleaje. En el uso clásico incluía tanto el varamiento deliberado como el accidental. La evidencia multilingüe conserva el contexto náutico: encallar, hicieron encallar, échouer. Es vocabulario técnico marítimo para el momento en que el casco toca fondo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2028', 'spa', 'ser llamado, llevar un nombre, recibir un título o designación', 'Este verbo significa dar nombre a algo, llamar a algo por un nombre o aplicar una designación. En Romanos 2:17, Pablo se dirige a quienes se llaman judíos o llevan ese nombre identitario. El uso clásico incluía aplicar palabras como nombres a cosas o llamar a personas por títulos específicos. La voz media enfatiza la autodesignación o identificación propia. La evidencia multilingüe muestra la variedad interpretativa: are-called, te llamas, appeler, todas girando en torno al acto de nombrar o designar, con distintos énfasis sobre quién otorga el nombre.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2030', 'spa', 'testigo ocular, observador presencial, quien ha visto personalmente', 'Este sustantivo designa a alguien que ha visto con sus propios ojos, un testigo ocular u observador directo. En 2 Pedro 1:16, los apóstoles afirman ser testigos oculares de la majestad de Cristo en la Transfiguración, sin seguir fábulas ingeniosas. El uso clásico incluía vigilantes y observadores, especialmente dioses que observaban los asuntos humanos, así como a los iniciados en el grado más alto de las religiones mistéricas. El Nuevo Testamento se apropia de este lenguaje de visión privilegiada para el testimonio apostólico. La evidencia multilingüe es uniforme: testigos oculares, eyewitnesses, Augenzeuge, enfatizando el testimonio visual directo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2031', 'spa', 'palabra, dicho, expresión; especialmente en sentido de locución breve o frase hecha', 'Este sustantivo significa palabra, expresión o dicho, particularmente en el sentido de una locución breve o giro idiomático. En Hebreos 7:9, el autor emplea la expresión ὡς ἔπος εἰπεῖν, un modismo clásico que significa ''por así decirlo'' o ''por decirlo brevemente'', al introducir una afirmación audaz sobre Leví pagando diezmos a través de Abraham. El uso clásico abarcaba desde palabras cantadas y promesas hasta oráculos y refranes proverbiales. Homero lo usaba para el habla acompañada de música. La evidencia multilingüe muestra enfoques interpretativos convergentes: word, palabra, parole, reconociendo esta voz como una unidad de discurso cuyo matiz depende del contexto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2032', 'spa', 'Celestial, celeste: perteneciente o propio del cielo, en contraste con lo terrenal. Adjetivo que marca personas, lugares o realidades como pertenecien', 'Celestial, celeste: perteneciente o propio del cielo, en contraste con lo terrenal. Adjetivo que marca personas, lugares o realidades como pertenecientes al ámbito celestial en vez del terrenal. Pablo lo emplea como contraste estructurante en 1 Corintios 15:40-49, distinguiendo cuerpos celestiales de terrenales y al Adán celestial del terrenal. Efesios usa el plural sustantivado «los celestiales» (ἐν τοῖς ἐπουρανίοις) como concepto espacial distintivo: el ámbito espiritual donde los creyentes están sentados con Cristo pero donde también operan poderes cósmicos (Efesios 1:3, 20; 2:6; 3:10; 6:12). Hebreos lo aplica a la vocación celestial (3:1), el don celestial (6:4) y el santuario celestial que el tabernáculo terrenal meramente copia (8:5).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2033', 'spa', 'Siete; numeral cardinal que con frecuencia porta significado simbólico de plenitud divina en el uso bíblico', 'Ἑπτά es el numeral griego indeclinable que significa «siete», y aparece 88 veces en el Nuevo Testamento con fuerza tanto literal como simbólica. Jesús alimenta a los cuatro mil con siete panes (Mt 15:36) y sobran siete canastas (Mt 15:37). El número domina el Apocalipsis —siete iglesias, siete sellos, siete trompetas, siete copas— donde señala de forma constante la totalidad divina. Incluso en el mandato de perdonar setenta y siete veces (Mt 18:22), el siete expresa plenitud sin límite. Todas las traducciones principales lo vierten con equivalentes directos del numeral.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2034', 'spa', 'siete veces, séptuplemente', 'Adverbio numérico directo que significa ''siete veces'', pero que en la enseñanza de Jesús adquiere un peso teológico que trasciende con mucho la aritmética. Cuando Pedro pregunta si perdonar siete veces es suficiente (Mt 18:21), Jesús responde con una multiplicación que destruye todo cómputo legalista. En Lucas 17:4, el mismo término aparece dos veces en un solo versículo, subrayando la plenitud radical del perdón. Todas las grandes tradiciones de traducción lo vierten con el numeral transparente — ''siete veces'' —, lo que confirma su significado unívoco.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2035', 'spa', 'siete mil; adjetivo numeral que designa la cantidad de siete millares', 'Este adjetivo numeral significa siete mil. En Romanos 11:4, Pablo cita la respuesta de Dios a Elías: ''Me he reservado siete mil hombres que no han doblado la rodilla ante Baal.'' El número representa el remanente fiel de Dios en Israel durante la época de Elías, y Pablo aplica esta teología del remanente a su propio tiempo. La evidencia multilingüe es completamente uniforme: todos los idiomas lo traducen directamente como siete mil, ya que los números se transfieren sin variación semántica entre lenguas. La importancia no radica en la palabra misma sino en lo que ese número específico representa teológicamente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2036', 'spa', 'decir, dijo; forma aorista del verbo ''decir''', 'Esta es la forma aorista (pasado simple) común que significa «dijo» o «habló». Mientras que el presente emplea λέγω y el futuro ἐρῶ, este aoristo εἶπον es la forma narrativa estándar para introducir el discurso directo. Aparece innumerables veces en los Evangelios y en Hechos para presentar las palabras de los personajes. Las tres ocurrencias específicas aquí pertenecen a Hechos 8-9, donde se registran momentos clave en la expansión de la iglesia primitiva.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2037', 'spa', 'Erasto; nombre propio de uno o varios cristianos mencionados por Pablo', 'Erasto (del griego Ἔραστος, ''amado'') es un nombre propio que aparece tres veces en el Nuevo Testamento, posiblemente refiriéndose a dos o tres personas distintas del círculo de Pablo. Un Erasto es enviado junto con Timoteo a Macedonia (Hechos 19:22), otro es identificado como tesorero de la ciudad de Corinto (Romanos 16:23), y un tercero permaneció en Corinto cuando Pablo escribió a Timoteo (2 Timoteo 4:20). La mención del tesorero sugiere un creyente con responsabilidad cívica notable.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2038', 'spa', 'Trabajar, obrar, realizar o producir; verbo en voz media para la actividad productiva, la ejecucion de obras y la obtencion de resultados.', 'Trabajar, obrar, realizar o producir; verbo en voz media para la actividad productiva, la ejecucion de obras y la obtencion de resultados.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2039', 'spa', 'Trabajo, negocio, oficio, ganancia; labor productiva o esfuerzo orientado al lucro o a un fin práctico.', 'Ἐργασία abarca todo el espectro desde el trabajo físico hasta la empresa comercial y la ganancia que esta produce. En Hechos, el término aparece en contextos económicos vívidos: la adivinación de una esclava generaba mucha ἐργασία (''ganancia'', Hch 16:16, 19), y Demetrio el platero reunió a sus compañeros de oficio advirtiendo que su ἐργασία (''negocio'', Hch 19:24-25) estaba amenazada. Lucas 12:58 lo emplea para el esfuerzo que uno debe invertir en resolver una disputa camino al tribunal. Pablo lo utiliza en Efesios 4:19 para referirse a la ''práctica'' de la impureza, extendiendo así el término del ámbito económico al moral.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2040', 'spa', 'Obrero, trabajador: el que realiza un trabajo, ya sea en el campo, un oficio o el ministerio del evangelio. ἐργάτης designa a una persona que trabaja:', 'Obrero, trabajador: el que realiza un trabajo, ya sea en el campo, un oficio o el ministerio del evangelio. ἐργάτης designa a una persona que trabaja: un jornalero, artesano o practicante. Jesús lo usa en su urgente llamado por obreros para la cosecha: «la mies es mucha, pero los obreros pocos» (Mateo 9:37-38; Lucas 10:2), y afirma que «el obrero es digno de su salario» (Lucas 10:7; 1 Timoteo 5:18). Pablo exhorta a Timoteo a ser «obrero que no tiene de qué avergonzarse» (2 Timoteo 2:15) y advierte contra «obreros fraudulentos» que se disfrazan de apóstoles de Cristo (2 Corintios 11:13; Filipenses 3:2). El término también aparece negativamente: «obreros de iniquidad» (Lucas 13:27).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2041', 'spa', 'Obra, acción, hecho; lo que una persona hace o produce, ya sea conducta moral, labor o empresa emprendida.', 'Un término amplio para lo que una persona realiza o lleva a cabo. En el Nuevo Testamento porta un peso teológico considerable: las ''obras de la ley'' de Pablo (Ro 2:7), la insistencia de Santiago en que la fe se manifiesta mediante las ''obras'' (Stg 1:25) y la presentación joánica de Jesús señalando sus ''obras'' como evidencia de autoridad divina (Jn 5:36). Un pequeño grupo de apariciones pasa de la evaluación moral a la idea de tarea o empresa, es decir, esfuerzo productivo más que conducta ética.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2043', 'spa', 'encallar, fijar firmemente, quedar clavado e inmóvil', 'Este verbo significa fijar firmemente, apuntalar o hacer que algo quede trabado e inmóvil. En Hechos 27:41, la proa del barco queda clavada en el banco de arena, completamente inmóvil mientras la popa se destroza por la fuerza de las olas. El uso clásico abarcaba apuntalar objetos, apilar cuerpos unos contra otros y cosas que quedaban encajadas o fijas. Las formas del perfecto pasivo subrayan el estado resultante: firmemente atascado, irremediablemente inmovilizado. La evidencia multilingüe refleja distintos enfoques interpretativos ante este naufragio: encallado, clavado, varado, todos capturando la idea de inmovilidad total.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2044', 'spa', 'proferir, declarar, proclamar con voz potente', 'Este verbo significaba originalmente mugir o bramar, como el sonido del ganado o el rugir del mar. Con el tiempo evolucionó para expresar la idea de proferir o declarar algo con fuerza y autoridad. En Mateo 13:35, citando el Salmo 78:2, describe la acción de proclamar cosas ocultas desde la fundación del mundo. La Septuaginta lo empleaba para el bramido del mar y el habla poderosa. La evidencia multilingüe muestra una interpretación teológica consistente: proferir, proclamar, declarar, todas sugiriendo un habla autoritativa más que un simple decir. El sentido clásico de rugido profundo enriquece la imagen de una proclamación que rompe un largo silencio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2045', 'spa', 'Escudriñar, examinar o investigar a fondo; indagación minuciosa de asuntos ocultos o profundos.', 'Transmite una búsqueda profunda y penetrante, no una mirada superficial sino una investigación exhaustiva de lo oculto o complejo. Jesús dice a los dirigentes judíos que escudriñen las Escrituras (Jn 5:39), y Pablo declara que el Espíritu ''todo lo escudriña, aun lo profundo de Dios'' (1 Co 2:10). Ya se aplique al estudio humano de la Escritura, a la penetración del Espíritu en las profundidades divinas o a la indagación de los profetas sobre el tiempo de la salvación (1 P 1:11), el vocablo siempre implica un examen meticuloso y deliberado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2046', 'spa', 'Decir, hablar, pronunciar; usado en voz activa para declarar algo y en pasiva en fórmulas proféticas de cumplimiento (''lo que fue dicho'').', 'Un verbo de habla versátil que abarca tanto la declaración activa como la cita pasiva. En voz activa cubre todo el espectro de decir, contar y hablar: los mandatos directos de Jesús, sus parábolas y promesas emplean esta palabra. Sus formas pasivas son especialmente prominentes en las fórmulas de cumplimiento profético de Mateo (''lo que fue dicho por medio del profeta''), donde el énfasis se desplaza del hablante a la declaración autoritativa misma. Un tercer uso, performativo, aparece cuando Jesús dice ''Os he llamado amigos'' (Jn 15:15), confiriendo un nuevo estatus relacional.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2047', 'spa', 'desierto, yermo, paraje desolado e inhabitado; región silvestre alejada de toda provisión humana', 'Este sustantivo evoca una extensión solitaria y desprovista de habitantes, asociada tanto a la privación física como a la prueba espiritual. Cuando Jesús alimenta a las multitudes, los discípulos protestan que la ἐρημία no ofrece alimento alguno (Mt 15:33; Mc 8:4). Pablo enumera los peligros del desierto junto a bandidos y naufragios (2 Co 11:26), y Hebreos 11:38 rinde homenaje a los fieles perseguidos que vagaron por desiertos y montañas. El griego ἐρημία transmite matices de abandono y desolación que el castellano ''desierto'' captura fielmente, aunque el término original subraya con más fuerza la ausencia total de refugio humano.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2048', 'spa', 'Desierto, yermo; lugar desolado o deshabitado; abandonado, asolado (en sentido profético)', 'En los Evangelios y Hechos, ἔρημος funciona principalmente como sustantivo que designa «el desierto», esa región geográfica austera donde Israel peregrinó, Juan el Bautista predicó y Jesús enfrentó la tentación (Mt 3:1; 4:1). Como adjetivo describe lugares apartados y solitarios adonde Jesús se retiraba a orar o donde las multitudes se reunían lejos de las aldeas (Mc 1:35; 6:31). Un tercer uso, cargado de fuerza profética, aparece cuando Jesús declara «vuestra casa os es dejada desierta» (Mt 23:38) y Pablo cita a Isaías sobre la mujer «desolada» que se alegrará (Gá 4:27). El español distingue con claridad entre desierto (geográfico) y desolada (abandono profético).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2049', 'spa', 'Asolar, devastar, dejar desolado; usado de reinos, ciudades e imperios comerciales destruidos por el juicio divino.', 'Describe la reducción devastadora de algo poblado o próspero a la vacuidad y la ruina. Jesús advierte que un reino o una casa dividida contra sí misma queda ''asolada'' (Matt 12:25; Luke 11:17), un principio con fuerza tanto política como espiritual. En Apocalipsis, la palabra adquiere una intensidad apocalíptica: la bestia y sus aliados devastan a Babilonia la Grande (Rev 17:16), y los mercaderes y capitanes de navío se lamentan al ver su inmensa riqueza reducida a desolación ''en una sola hora'' (Rev 18:17, 19). El término transmite una destrucción violenta y definitiva.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2050', 'spa', 'Desolación, devastación; el acto o estado de quedar completamente arruinado y desierto', 'Este sustantivo describe el acto de dejar algo desolado o el estado resultante de devastación y abandono total. Aparece exclusivamente en el discurso apocalíptico de los Sinópticos, en referencia a la «abominación desoladora» de Daniel, un símbolo profético de profanación y juicio. El término evoca la ruina absoluta, ya sea del templo de Jerusalén en el año 70 d.C. o de la tribulación escatológica. Conlleva matices de juicio divino que resulta en una destrucción completa e irreversible.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2051', 'spa', 'contender, disputar, porfiar', 'Este verbo significa contender, disputar o porfiar, es decir, enzarzarse en rivalidad o controversia. En Mateo 12:19, citando Isaías 42:2, describe lo que el Siervo no hará: ''No contenderá ni gritará.'' El uso clásico abarcaba desde la competición atlética hasta la disputa verbal y el conflicto militar. La Septuaginta lo empleaba para la contienda legal y la discordia. La evidencia multilingüe es consistente: contender, disputar, porfiar, todas enfatizando la confrontación o el conflicto. El contexto de Mateo subraya lo que el Siervo evita: la discusión contenciosa, la disputa pública y el ruido de la controversia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2052', 'spa', 'Ambición egoísta o rivalidad facciosa; partidismo interesado que fragmenta la comunidad en beneficio propio.', 'Derivada de una raíz que significa ''trabajar por jornal'', ἐριθεία pasó a designar el proselitismo mercenario de los aspirantes a cargos políticos y, finalmente, cualquier faccionalismo autopromocional. Pablo la empareja repetidamente con los celos (ζῆλος) como destructores gemelos de la comunión. En Filipenses 2:3 se presenta como el opuesto exacto de la mente humilde y altruista de Cristo. La idea central es la búsqueda del provecho personal a expensas de la comunidad, ya sea en la iglesia o en cualquier ámbito de convivencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2054', 'spa', 'Contienda, discordia, riña; discordia nacida de la rivalidad, los celos o la ambición egoísta.', 'Sustantivo que denota discordia interpersonal, rivalidad y espíritu pendenciero. Pablo lo sitúa constantemente en listas de vicios junto a los celos, la ira y la ambición egoísta: ese racimo tóxico de conductas que fractura la comunidad. Aparece en Romanos 1:29 entre los pecados de una mente entenebrecida, en 1 Corintios 1:11 y 3:3 como evidencia de la inmadurez de los corintios, y en Gálatas 5:20 entre las obras de la carne. No se trata de un simple desacuerdo, sino del espíritu venenoso del partidismo y la facción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2055', 'spa', 'cabrito, chivo joven', 'Este sustantivo es una forma diminutiva que significa cabrito o chivo joven, es decir, una cabra pequeña. En Mateo 25:33, Jesús emplea la imagen de separar las ovejas de los cabritos en su parábola del juicio. La forma diminutiva podría sugerir afecto o simplemente indicar animales jóvenes. El uso clásico incluía tanto la cabra joven literal como referencias botánicas. La evidencia multilingüe es directa: cabritos, chevreau, young goats, todas identificándolos como cabras pequeñas. En el sacrificio judío y la agricultura mediterránea, las cabras eran ganado común, haciendo de esta una imagen pastoral familiar para la audiencia de Jesús.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2057', 'spa', 'Hermas (nombre propio)', 'Este es un nombre personal: Hermas, un cristiano saludado por Pablo en Romanos 16:14. El nombre es una forma dórica relacionada con Hermes, el dios griego. No se sabe nada más sobre este individuo aparte del saludo de Pablo. El nombre aparece en la literatura cristiana primitiva (El Pastor de Hermas), aunque probablemente no se trate de la misma persona. La evidencia multilingüe muestra cómo se transfieren los nombres propios: la mayoría conserva ''Hermas'' con leves variaciones (Hermán) que reflejan la fonología local. Los nombres personales típicamente no se traducen sino que se transliteran, preservando la identidad del individuo a través de las lenguas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2059', 'spa', 'Traducir, interpretar; trasladar de un idioma a otro o explicar el significado', 'Este verbo significa interpretar lenguas extranjeras, traducir entre idiomas o explicar y exponer un significado. En el uso clásico abarca tanto la traducción lingüística como la explicación en sentido más amplio. En el Nuevo Testamento aparece cuando los escritores de los Evangelios traducen nombres y palabras arameas o hebreas para los lectores griegos, explicando el nuevo nombre de Simón (Juan 1:42), el significado de Siloé (Juan 9:7) y el nombre de Melquisedec (Hebreos 7:2).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2061', 'spa', 'Hermógenes (nombre propio)', 'Nombre propio: Hermógenes, mencionado en 2 Timoteo 1:15 como uno de los que se apartaron de Pablo, junto con todos los de Asia. El nombre significa ''nacido de Hermes'', un nombre teofórico griego muy común en la antigüedad. No sabemos nada más sobre este individuo fuera de esta referencia negativa. La evidencia multilingüe muestra un tratamiento estándar del nombre mediante transliteración, conservando la forma griega (Hermogenes, Hermogénēs). Su inclusión en las Escrituras inmortaliza su abandono de Pablo, aunque las circunstancias específicas permanecen desconocidas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2062', 'spa', 'reptil, animal rastrero; toda criatura que se arrastra o repta por el suelo', 'Derivado del verbo que significa ''arrastrarse'', este sustantivo abarca la amplia categoría de criaturas que se desplazan pegadas al suelo: serpientes, lagartos, insectos y animales similares. En la visión de Pedro desciende un gran lienzo lleno de cuadrúpedos, reptiles y aves (Hch 10:12; 11:6), donde esta categoría representa a las criaturas ritualmente impuras que Dios ahora declara limpias. Pablo emplea el término en Romanos 1:23 para ilustrar la degradación de la idolatría, y Santiago 3:7 incluye a los reptiles entre las criaturas salvajes que la humanidad ha logrado domesticar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2064', 'spa', 'Venir, llegar, acercarse; movimiento físico, título mesiánico, llamamiento imperativo y referencia temporal atributiva.', 'Uno de los verbos más frecuentes del Nuevo Testamento, ἔρχομαι abarca todo el espectro de la llegada y el acercamiento. En su núcleo significa venir o llegar a un destino, pero su forma participial ὁ ἐρχόμενος se convirtió en un título mesiánico cargado de significado: ''el que viene,'' eco del Salmo 118:26 y de la expectativa profética de Malaquías. En imperativo funciona como llamamiento directo (''¡Ven!''), y en uso atributivo marca el tiempo futuro (''la era venidera''). El contexto ocasionalmente lo extiende a ''entrar'' o incluso ''ir,'' mostrando cuán flexibles son los verbos de movimiento en griego.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2065', 'spa', 'Pedir, rogar; o bien preguntar para obtener información — dos acepciones que a menudo se entrelazan en contexto', 'Un verbo griego frecuente cuyas dos acepciones —solicitar y preguntar— se solapan con facilidad. Cuando significa «rogar» o «suplicar», conlleva el peso de una apelación personal, como cuando la mujer sirofenicia ruega a Jesús que expulse un demonio (Mc 7:26) o los discípulos le piden que despida a la multitud (Mt 15:23). El español capta este matiz con «rogar» y «pedir». Cuando significa «inquirir» o «cuestionar», aparece en escenas de genuina indagación: Jesús pregunta a los discípulos quién dice la gente que es él (Mt 16:13) o nadie se atreve a preguntarle más (Jn 16:23). Aquí el español emplea «preguntar», una distinción que el inglés no posee pero que la evidencia multilingüe hace patente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2066', 'spa', 'Vestidura, indumentaria; prenda exterior que connota distinción o formalidad.', 'Derivado de ἕννυμι (''vestir''), ἐσθής designa ropa o vestidura con un matiz de dignidad o solemnidad. Herodes viste a Jesús con ''ropas espléndidas'' (ἐσθῆτα λαμπράν, Lc 23:11), y los ángeles en el sepulcro y la ascensión aparecen con vestiduras blancas resplandecientes (Lc 24:4; Hch 1:10). Cornelio ve una figura con ''ropa brillante'' (Hch 10:30), y Herodes Agripa se reviste de vestiduras reales antes de su fatal audiencia (Hch 12:21). El español «vestidura» preserva el registro formal, distinguiéndola de términos más cotidianos como ἱμάτιον.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2067', 'spa', 'vestimenta, ropa, vestiduras; lo que uno lleva puesto', 'Sustantivo sencillo que significa vestimenta o ropa. Derivado del verbo ''vestir'' (ἐσθέω), designa las prendas en general y no artículos específicos. El griego clásico y bíblico lo usa de modo intercambiable con términos similares para indumentaria. La palabra no lleva connotaciones especiales: simplemente se refiere a la realidad cotidiana de lo que la gente viste. En contextos bíblicos puede aparecer junto a discusiones sobre provisión, modestia o transformación, como cuando las vestiduras de Jesús se volvieron resplandecientes en la Transfiguración.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2068', 'spa', 'Comer alimento; por extensión, consumir o devorar en sentido destructivo o figurado', 'El verbo griego estándar para comer, empleado a lo largo de los Evangelios y las Epístolas para comidas ordinarias, la cena pascual, alimentaciones milagrosas y debates sobre las leyes alimentarias. Jesús come con publicanos y pecadores (Mt 9:11), los discípulos arrancan espigas en sábado y comen (Mt 12:1), y Pablo aborda si los creyentes pueden comer alimentos ofrecidos a los ídolos (1 Co 8:7-13). En un llamativo uso figurado, se dice que el «furor del fuego» consumirá a los adversarios de Dios (Heb 10:27), pasando del sentido de nutrición al de aniquilación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2069', 'spa', 'Eslí (nombre propio)', 'Nombre propio: Eslí (o Heslí), un antepasado de Jesús que aparece en la genealogía de Lucas (3:25). Este nombre solo figura aquí en las Escrituras. Posiblemente sea de origen hebreo, aunque su etimología es incierta. La evidencia multilingüe muestra la variación típica en la transliteración de nombres: Hesli, Heslí, Esli, ya que distintas tradiciones manuscritas preservaron diferentes vocalizaciones. La genealogía de Lucas traza el linaje humano de Jesús a través de antepasados poco prominentes, y Eslí es uno de aquellos conocidos únicamente por el registro genealógico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2070', 'spa', 'ser, existir (verbo de existencia); forma de εἰμί con variantes dialectales completas', 'El verbo griego fundamental de existencia y ser, que aparece en innumerables formas a través de los dialectos: eólico ἔμμι, dórico ἐντί, variaciones épicas y jónicas. Expresa existencia simple (''yo soy''), predicación (''la palabra es verdad'') y ubicación (''él está en el templo''). Los autores del Nuevo Testamento heredan el peso filosófico y teológico de este verbo: en la Septuaginta traduce la autorrevelación de Dios a Moisés (''YO SOY EL QUE SOY''), y en el Evangelio de Juan las declaraciones de Jesús ''Yo soy'' evocan la identidad divina. Su ubicuidad lo hace invisible hasta que porta carga teológica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2071', 'spa', 'ser, existir (forma futura de εἰμί); será, habrá de ser', 'El tiempo futuro del verbo fundamental «ser/estar», que expresa lo que existirá, sucederá o llegará a cumplirse. A lo largo de los dialectos griegos adopta formas variadas, pero siempre apunta hacia adelante en el tiempo. Los textos proféticos y apocalípticos dependen fuertemente de este verbo: lo que ha de venir, lo que será revelado, la era que llegará. Jesús lo emplea en el discurso escatológico («habrá señales»), y Pablo lo utiliza al tratar las realidades de la resurrección. El futuro del ser porta tanto promesa como advertencia a lo largo de las Escrituras.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2073', 'spa', 'Tarde, atardecer; el momento del día desde la última hora de la tarde hasta el anochecer', 'Este sustantivo femenino designa la tarde o el atardecer, la parte final del día cuando la luz se desvanece. En el uso clásico podía indicar simplemente «tarde» o, de manera más amplia, «el occidente» (donde se pone el sol). En el Nuevo Testamento marca el momento del día en diversos eventos: los discípulos de Emaús instando a Jesús a quedarse porque la tarde se acerca (Lucas 24:29), la imposibilidad de juzgar prisioneros de noche (Hechos 4:3) y la prolongada sesión de enseñanza de Pablo (Hechos 28:23).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2074', 'spa', 'Hesrón; nombre propio de un antepasado en la genealogía de Jesús', 'Hesrón (del hebreo חֶצְרוֹן) es un nombre propio de la historia de Israel, identificado como hijo de Fares y antepasado del rey David. Aparece en los registros genealógicos que vinculan a Jesús con Abraham y David. Este nombre conecta a Jesús con el linaje tribal de Judá y establece su derecho legal como Mesías descendiente de David a través de la simiente prometida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2075', 'spa', 'ser, existir (forma imperfecta de εἰμί); era, eran, solía ser', 'El tiempo imperfecto del verbo «ser/estar», que describe estados pasados, existencia continuada o condiciones habituales en tiempo pasado. En la narrativa sirve para establecer la escena («había un hombre»), proveer el trasfondo («Jesús estaba enseñando») o describir circunstancias («los discípulos estaban en la barca»). A diferencia del aoristo, que puntualiza eventos pasados, el imperfecto se demora en la duración: lo que estaba ocurriendo, lo que alguien solía ser, cómo eran las cosas antes de que el cambio llegara.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2076', 'spa', 'es, existe (tercera persona singular presente de εἰμί); él/ella es', 'La tercera persona del singular en presente del verbo «ser/estar», probablemente la forma más frecuente en toda la literatura griega. Afirma existencia, identifica o predica: «Dios es amor», «esto es mi cuerpo», «bienaventurado el que». En los dialectos griegos aparece como ἐστί (forma estándar), ἐντί (dórica) y otras variantes. Los escritores bíblicos la emplean para la revelación («este es el Hijo de Dios»), la metáfora («yo soy la vid, vosotros los pámpanos») y la afirmación teológica. Simple, omnipresente y fundacional.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2077', 'spa', 'sea, que sea (tercera persona singular imperativo de εἰμί); optativo de permiso o mandato', 'El imperativo de tercera persona del verbo «ser», que expresa permiso, mandato o deseo: «que así sea», «que él sea». Esta forma concede existencia, permite que un estado continúe o invoca una condición. En la oración y la bendición posee fuerza performativa: no solo describe, sino que realiza. La respuesta de María, «hágase en mí según tu palabra», emplea una construcción afín. Los dialectos griegos muestran variaciones características (ἔστω es más común; ἤτω aparece en textos tardíos). El modo imperativo convierte al ser mismo en asunto de voluntad y decreto divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2078', 'spa', 'Último, final, postrero; referido al término de una secuencia temporal o al extremo del espacio', 'Derivado de una raíz que significa «fuera de» o «lo más externo», este adjetivo señala el punto terminal de cualquier secuencia, ya sea temporal o espacial. En el Nuevo Testamento su uso abrumadoramente temporal le confiere un profundo peso escatológico: «los últimos días» (Hch 2:17), «la última trompeta» (1 Co 15:52), «el último enemigo» (1 Co 15:26). La sentencia de Jesús «los últimos serán primeros» (Mt 19:30) subvierte las expectativas sociales mediante el sentido ordinal. El raro uso espacial —«hasta lo último de la tierra» (Hch 1:8)— evoca Isaías 49:6 y traza el alcance geográfico de la misión evangélica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2079', 'spa', 'Extremadamente, a punto de (morir), in extremis', 'Este adverbio, derivado del adjetivo ἔσχατος (último, extremo), significa extremadamente o en el extremo, en el límite más lejano de algo. En Marcos 5:23, Jairo dice que su hija está ''a punto de morir'' o ''en su última extremidad'': ἐσχάτως ἔχει. La expresión es idiomática y significa estar in extremis, al borde de la muerte. En el uso clásico, ἔσχατος describía extremos geográficos, finales temporales y condiciones superlativas. La evidencia multilingüe muestra glosas interpretativas: a punto de muerte, al extremo, enfatizando cómo el adverbio intensifica la frase verbal para significar ''está gravísima'' o ''está muriendo''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2080', 'spa', 'Adentro, dentro; adverbio o preposición que indica el interior de un espacio o la naturaleza interna de una persona.', 'Adverbio que significa ''adentro'' o ''dentro'', usado tanto en sentido espacial como antropológico. Espacialmente, describe estar dentro de un patio (Mt 26:58; Mr 14:54; Mr 15:16), detrás de puertas cerradas (Jn 20:26) o dentro de una prisión vigilada (Hch 5:23). Antropológicamente, Pablo emplea ''el hombre interior'' (ὁ ἔσω ἄνθρωπος) para referirse al ser espiritual que se renueva día a día aunque el hombre exterior se desgaste (2 Co 4:16; Ef 3:16). El español distingue ''adentro'' (direccional) de ''dentro'' (locativo), reflejando la flexibilidad de esta palabra entre movimiento y posición.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2081', 'spa', 'Adverbio espacial formado de ἔσω (''dentro'') más el sufijo -θεν que indica origen o ubicación. Sus 12 apariciones en el NT transitan fluidamente entre ', 'Adverbio espacial formado de ἔσω (''dentro'') más el sufijo -θεν que indica origen o ubicación. Sus 12 apariciones en el NT transitan fluidamente entre la interioridad literal y la figurada. Jesús lo usa con devastador efecto retórico en sus ayes contra los fariseos: sus copas y sepulcros pueden parecer limpios por fuera, pero ἔσωθεν rebosan de avaricia e hipocresía (Mt 23:25, 27). Marcos 7:21-23 sitúa la fuente de la contaminación moral ἔσωθεν, ''de dentro'' del corazón humano. Apocalipsis 4:8 y 5:1 lo aplican físicamente — ojos cubriendo a las criaturas vivientes ''por dentro'' y escritura en un rollo ''por dentro''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2083', 'spa', 'compañero, amigo; forma de tratamiento dirigida a un asociado o camarada', 'Este sustantivo significa camarada, compañero o amigo, y se usaba en el griego clásico para referirse a compañeros de armas, comensales o socios. En el Nuevo Testamento aparece exclusivamente en el Evangelio de Mateo como vocativo, es decir, como forma de dirigirse a alguien. A diferencia de φίλος, el término es más neutral y a veces conlleva un tono de ironía o distancia. Jesús lo emplea tres veces, siempre en momentos decisivos al dirigirse a alguien en parábolas o encuentros reales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2084', 'spa', 'De lengua extranjera, que habla en otras lenguas', 'Este adjetivo significa que habla una lengua o idioma extranjero, que se caracteriza por un idioma diferente al propio. En 1 Corintios 14:21, Pablo cita Isaías 28:11 acerca de Dios hablando a Israel por medio de personas de lenguas extranjeras: los invasores asirios cuyo idioma extraño era señal de juicio. El compuesto combina ἕτερος (otro) con γλῶσσα (lengua/idioma). El uso clásico describía tanto a hablantes extranjeros como diversidad lingüística. La evidencia multilingüe varía: otras lenguas, parlant d''autres langues, algunas enfatizando la diversidad lingüística, otras la extranjería.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2086', 'spa', 'Estar desigualmente unidos bajo un yugo, asociarse en alianza incompatible, especialmente con incrédulos', 'Este raro verbo compuesto aparece únicamente en la advertencia de Pablo contra formar asociaciones desiguales con los incrédulos (2 Corintios 6:14). La metáfora agrícola proviene de la prohibición en Deuteronomio de uncir juntos animales diferentes: bueyes y asnos trabajaban a ritmos y fuerzas distintas, haciendo imposible el arado eficaz. Pablo extiende esta imagen a las asociaciones espirituales donde la incompatibilidad fundamental impide una colaboración fructífera. El término es un hápax legómenon que combina ἕτερος (diferente) con ζυγός (yugo), creando una imagen vívida de desigualdad en la alianza.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2087', 'spa', 'Otro, diferente; designa una entidad adicional, distinción cualitativa, o el siguiente en secuencia temporal.', 'Un adjetivo fundamental de distinción y alternancia. En su núcleo señala a ''otro'': un segundo amo en Mateo 6:24, la siguiente ciudad en Mateo 10:23. Pero a diferencia del cuasisinónimo ἄλλος, ἕτερος conlleva un matiz de diferencia cualitativa que aflora explícitamente en pasajes como 2 Corintios 11:4 (''un evangelio diferente''). Ocasionalmente se estrecha hacia la sucesión temporal — ''el día siguiente'' en Hechos 20:15 — mostrando cómo la ''otredad'' puede deslizarse de la categoría a la secuencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2088', 'spa', 'De manera diferente, de otro modo; de forma distinta a la esperada o habitual', 'Este adverbio modifica la manera en que algo se realiza o se piensa, señalando un enfoque alternativo o una perspectiva distinta. Pablo lo emplea en Filipenses 3:15 como parte de su confianza en que Dios revelará la verdad a quienes piensan ''de manera diferente'' sobre ciertos asuntos. La palabra sugiere variación sin implicar necesariamente error, reconociendo con generosidad que los creyentes pueden llegar a diferentes comprensiones en cuestiones secundarias, confiando en la guía divina para la clarificación final.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2089', 'spa', 'Todavía, aún; marca continuidad temporal o, con negación, cesación (''ya no, no más'')', 'Un adverbio griego de tiempo muy frecuente que señala que algo sigue en curso o persiste hasta un momento dado. En su uso afirmativo significa «todavía» o «aún», como cuando se dice que el Padre aún habla (Mt 17:5). Cuando se combina con partículas negativas como οὐκέτι o μηκέτι, el sentido se invierte a «ya no» o «no más», como en Hebreos 10:2, donde la conciencia ya no acusa. El alemán «noch», el francés «encore» y el hebreo עוֹד reflejan esta doble capacidad de un único marcador temporal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2090', 'spa', 'Preparar, disponer o alistar algo para un proposito; tambien estar en estado de preparacion.', 'Preparar, disponer o alistar algo para un proposito; tambien estar en estado de preparacion.');